/* Original synthetic practice content. Versioned learning material, not a secure selection test. */
window.CASE_ARCHIVE=[{"id":"kpi-paradoksu","title":"İyileşen ekipler, düşen toplam","level":1,"kind":"Veri analizi","minutes":30,"roles":["analyst","graduate","operations"],"skills":["Oran ve payda","Veri yorumlama","Yönetici özeti"],"brief":"Ardıç Hizmet, iki kanaldan gelen talepleri aynı teslim standardıyla karşılıyor. İki kanalın yöneticisi de gelişim bildirdi; genel müdür ise toplam oranın düştüğünü söylüyor. Yeni analist olarak toplantıya bir sayfalık açıklama hazırlayacaksın.","mandate":"İki dönemi aynı tanımla karşılaştır. Çalışan veya kanal hakkında neden-sonuç hükmü vermeden toplam değişimi ve karar için gereken ek bilgiyi açıkla.","docs":[{"title":"Teslimat dökümü","text":"Dönemler 20 iş günüdür. Her talep tek kanalda ve tek dönemde sayılmıştır. İptaller dışarıdadır. Zamanında: söz verilen tarihte tamamlanmış. Adetler kişi başına verim ölçmez.","headers":["Dönem","Kanal","Toplam talep","Zamanında"],"rows":[["Önceki","Web",800,760],["Önceki","Mağaza",200,160],["Son","Web",200,194],["Son","Mağaza",800,664]],"file":"/cases/packs/kpi-paradoksu-1.csv"},{"title":"Toplantı notu","text":"Web yöneticisi: “%95’ten %97’ye çıktık.” Mağaza yöneticisi: “%80’den %83’e çıktık.” Genel müdür: “Toplam kayıp varsa iki ekip de kötüleşmiştir.” Kanal karmasının neden değiştiği henüz araştırılmadı. Önceki dönemin %80 Web / %20 Mağaza karmasını karşılaştırma ağırlığı olarak kullanabilirsin.","headers":[],"rows":[]}],"tasks":["Her kanalın ve şirket toplamının iki dönem oranlarını hesapla. Yüzde ile yüzde puanını ayır.","Önceki dönem kanal ağırlıkları sabit kalsaydı son dönemin oranını hesapla. Bu karşılaştırmanın neyi açıklamadığını belirt.","Genel müdür için en fazla 150 kelimelik bir not yaz: bulgu, kanıt, karar öncesi iki soru.","İlk hafta için kanal karması ve hizmet seviyesi takibini nasıl kuracağını yaz."],"numbers":[{"id":"onceki","label":"Önceki dönem toplam zamanında oranı","value":92,"unit":"%","tolerance":0.05,"why":"(760+160)/(800+200) × 100 = 92."},{"id":"son","label":"Son dönem toplam zamanında oranı","value":85.8,"unit":"%","tolerance":0.05,"why":"(194+664)/1000 × 100 = 85,8; değişim −6,2 yüzde puanı."},{"id":"sabit","label":"Sabit önceki dönem karmasıyla son dönem oranı","value":94.2,"unit":"%","tolerance":0.05,"why":"0,80 × 97 + 0,20 × 83 = 94,2. Sabit karmada artış 2,2 yüzde puanıdır."}],"rubric":[{"name":"Payda ve hesap doğruluğu","evidence":"Oranları toplam adetlere göre hesaplar; kanal yüzdelerinin basit ortalamasını almaz."},{"name":"Karma etkisini açıklama","evidence":"Her iki kanal iyileşirken düşük oranlı kanalın payı arttığı için toplamın düşebildiğini sayılarla açıklar."},{"name":"Çıkarım sınırı","evidence":"Karma değişiminin nedenini veya ekip verimliliğini bu tablodan bildiğini iddia etmez."},{"name":"İletişim ve takip","evidence":"Kısa yönetici notunda sonuç, veri ve ihtiyaç duyulan bilgiyi ayırır; sabit tanımlı takip önerir."}],"update":{"title":"Yeni istek: tek hedef","text":"Genel müdür bir sonraki ay için %90 toplam hedef istiyor. Son dönem kanal oranları değişmeden kalırsa Web payı en az ne olmalı? Hedefin yalnız kanal karmasını değiştirerek sağlanmasının iş açısından hangi sorunu yaratabileceğini tartış.","reference":"97w + 83(1−w) ≥ 90 → w ≥ 0,50. Bu matematiksel koşul, talebi yönlendirmek için ticari gerekçe değildir; zor kanalı dışlamak ölçütü iyileştirip hizmeti kötüleştirebilir."},"solution":["İki yöneticinin kanal oranları doğrudur; genel müdürün ekiplerin kötüleştiği çıkarımı desteklenmez.","Toplam oran gerçek hizmet deneyiminin bir özetidir. Sabit karma oranı ise dönemleri karşılaştıran ek göstergedir; biri diğerinin yerine geçmez.","Kanal bazında talep türü, söz verilen süre ve karma değişiminin nedenleri araştırılmalı. Haftalık raporda toplam hacim, kanal oranı ve karma birlikte gösterilebilir."],"pitfalls":["%97 ile %83’ü eşit ağırlıkla ortalamak.","Toplam düşüşü çalışan performansına veya isteksizliğine bağlamak.","Sabit karma sonucunu gerçekleşmiş %94,2 hizmet gibi sunmak."],"questions":["Ağırlıkları başka bir dönemden seçseydin yorum nasıl değişirdi?","Kanal bazında da talep zorluğu değişmiş olsaydı neyi kontrol ederdin?"],"version":"1.0.0","candidateFile":"/cases/packs/kpi-paradoksu-aday.md"},{"id":"vardiya-darbogazi","title":"Kapasite var, sipariş yetişmiyor","level":1,"kind":"Karar ve sunum","minutes":35,"roles":["operations","analyst","graduate"],"skills":["Kapasite","Darboğaz","Uygulama planı"],"brief":"Koru Dağıtım’da bugünkü 1.200 siparişin vardiya sonunda çıkması bekleniyor. Toplama ekipleri boşluk olduğunu, paketleme ise yetişemediğini söylüyor. Sen vardiya planını yeniden düzenleyeceksin.","mandate":"Kalite kontrol adımlarını kaldırmadan ve ek personel almadan uygulanabilir ilk planı kur. İş sürelerinin standart varsayım olduğunu, değişkenlik payı verilmediğini göz önünde bulundur.","docs":[{"title":"İş yükü ve süre","text":"Her sipariş bir kez toplanır ve bir kez paketlenir. İş süreleri dakika/sipariştir. Paketleme her sipariş için 1 dakikadır; toplama ve paketleme ardışık süreçlerdir. Her kişinin 300 net çalışma dakikası vardır.","headers":["Sipariş türü","Adet","Toplama dk/sipariş"],"rows":[["Küçük",900,1],["Büyük",300,3]],"file":"/cases/packs/vardiya-darbogazi-1.csv"},{"title":"Ekip ve yetki","text":"Toplama ekiplerinden herkes paketleme eğitimi almıştır. Küçük ve büyük toplama eğitimleri ise birbirinin yerine geçmez. Gün başında bir personeli bütün gün paketlemeye alabilirsin. Kişi aynı anda iki görevde sayılmaz.","headers":["Ekip","Kişi","Net dk/kişi"],"rows":[["Küçük toplama",4,300],["Büyük toplama",4,300],["Paketleme",3,300]],"file":"/cases/packs/vardiya-darbogazi-2.csv"},{"title":"Kontrol noktaları","text":"İlk 60 dakikada paketlemeye yetecek hazır iş vardır. Vardiya içi akışın tamamen kesintisiz olduğunu varsayma; 60 dakikada bir kalan iş ve fiili hız kontrolü planla. Kalite standardı değiştirilemez. Fiziksel taşıma ve ekipman sorunlarına ilişkin veri yoktur.","headers":[],"rows":[]}],"tasks":["Toplama iş yükünü, her ekibin kapasitesini ve paketleme açığını hesapla.","En az iki personel dağılımı seçeneğini karşılaştır; birini gerekçesiyle seç.","İlk saat ve vardiya ortası kontrolünü yaz. Planın hangi varsayım bozulursa çalışmayacağını belirt.","Ekibe göndereceğin kısa görev değişikliği mesajını hazırla."],"numbers":[{"id":"toplama","label":"Toplam toplama iş yükü","value":1800,"unit":"dk","tolerance":0.1,"why":"900×1 + 300×3 = 1.800 dakika."},{"id":"acik","label":"Başlangıç paketleme kapasite açığı","value":300,"unit":"dk","tolerance":0.1,"why":"1.200×1 − 3×300 = 300 dakika."},{"id":"transfer","label":"Açığı kapatmak için asgari tam vardiya transferi","value":1,"unit":"kişi","tolerance":0,"why":"Küçükten veya büyükten bir kişi paketlemeye geçerse kalan üç kişi ilgili 900 dakikalık yükü karşılar; paketleme 4×300=1.200 olur."}],"rubric":[{"name":"Ayrı süreç kapasitesi","evidence":"Toplama boşluğunun paketleme açığını kendiliğinden kapatmadığını gösterir."},{"name":"Yetkinlik ve kişi tutarlılığı","evidence":"Transfer sonrası kaynak ekibin kapasitesini kontrol eder, kişiyi çift saymaz."},{"name":"Kırılganlık ve kontrol","evidence":"Tam kapasite planında tampon olmadığını söyler; fiili hız ve hazır iş takibi koyar."},{"name":"Uygulanabilir iletişim","evidence":"Kimin hangi anda ne yapacağını, kontrol zamanını ve eskalasyon koşulunu açıklar."}],"update":{"title":"Vardiya ortasında ek talep","text":"60 büyük sipariş daha geldi. İlk planında küçük toplama ekibinden bir kişiyi paketlemeye almıştın. Toplama için kalan süre yeterli olsa bile toplam gün hesabında hangi yeni kapasite açığı doğar? Ek iş için net 60 kişi-dakika paketleme desteği sağlanabiliyor; bunun zamanlamasını nasıl doğrularsın?","reference":"Büyük toplama yükü 360×3=1.080 dk ve dört kişinin 1.200 dk kapasitesi içindedir. Paketleme 1.260 dk yük/1.200 dk kapasite → 60 kişi-dakika açık. Desteğin geç saatte gelmesi son çıkış saatini kurtarmayabilir; bitiş ve akış kontrolü gerekir."},"solution":["Bir küçük toplayıcıyı paketlemeye al: küçük 900/900 dk, büyük 900/1.200 dk, paketleme 1.200/1.200 dk. Büyükten transfer de başlangıç yüklerinde matematiksel olarak mümkündür.","İlk plan tam kapasitededir; standart süreler saparsa, ekipman veya hazır iş sorunu çıkarsa teslimat riske girer. Büyük ekibindeki boşluk otomatik olarak paketleme tamponu değildir; zamanlı destek planlanabilir.","Çıkış hedefini kaliteyi kaldırarak sağlamak kabul edilebilir alternatif değildir."],"pitfalls":["Toplam insan dakikasını toplayıp her sürecin yetiştiğini varsaymak.","Transfer edilen kişiyi toplama kapasitesinde tutmaya devam etmek.","Ek 60 siparişi 60 dakika toplama işi saymak."],"questions":["Personeli büyük ekipten alsaydın ek talep karşısında ne değişirdi?","Gerçek çalışma süreleri değişkense hangi veriyi ilk saat toplardın?"],"version":"1.0.0","candidateFile":"/cases/packs/vardiya-darbogazi-aday.md"},{"id":"gelen-kutusu","title":"İlk sabah: her şey acil","level":1,"kind":"Önceliklendirme","minutes":30,"roles":["graduate","analyst","lead","custom"],"skills":["Öncelik","Yetki","İletişim"],"brief":"Pazartesi 09.00. Yeni başladığın bir destek ekibinde 12.00’ye kadar görev başındasın. Masanda sekiz mesaj var. Tüm işleri kendin yapamazsın; gerekçeli bir plan ve yanıtlar hazırlaman bekleniyor.","mandate":"İlk 15 dakikayı, 09.00–12.00 planını ve devirleri belirle. Delege ettiğin işin sahibini ve geri dönüş saatini yaz; yetkin olmayan bir onayı başkasına devretme.","docs":[{"title":"Gelen kutusu","text":"Süreler işi kendin yaparsan gereken net dakikadır. Öncelik numarası mesajı gönderen kişinin talebidir, zorunlu sıralama değildir.","headers":["ID","Saat / son tarih","Mesaj","Süre dk"],"rows":[["M1","Hemen","Koridorda su sızıntısı; geçişte kayma riski var. Tesis sorumlusu ulaşılabilir.",15],["M2","09.45","Yönetim toplantısı için üç slayt; veri hazır, düzenleme gerekiyor.",30],["M3","10.30","Müşteriye gecikme açıklaması. Analistin doğrulanmış verisi 09.50’de gelecek.",20],["M4","11.00","Bordro istisnası onayı; yetki yalnız sende. Ayrıntı bordro uzmanında.",15],["M5","11.00","Ziyaretçi karşılama; resepsiyon ekibi yapabilir.",20],["M6","Bugün 17.00","Eğitim materyalindeki görselleri yenile.",45],["M7","16.00","Tedarikçi tekliflerini karşılaştır; satın alma uzmanı destek verebilir.",30],["M8","Belirsiz","Bir çalışma arkadaşı, personele ait ham dosyayı kişisel e-postasına göndermeni istiyor.",10]],"file":"/cases/packs/gelen-kutusu-1.csv"},{"title":"Yetki ve kaynak","text":"Tesis sorumlusu güvenlik önlemini alabilir; kendin tesisat müdahalesi yapma. Resepsiyon ve satın alma uzmanı görev alabilir, teyit gerekir. Bordro uzmanı hazırlık yapabilir ama son onay sende kalır. Kişisel e-postaya dosya aktarımı için onaylı bir gerekçe/kanal bilgisi yok. Devir mesajları için birkaç dakika koordinasyon payı bırak.","headers":[],"rows":[]},{"title":"Başarı tanımı","text":"Tüm işleri bitirmek değil, güvenlik riskini geciktirmemek, kritik taahhütleri korumak ve değişen beklentileri zamanında bildirmek bekleniyor. 09.50 öncesi müşteri yanıtını taslaklayabilirsin; doğrulanmamış bilgiyi kesin sonuç gibi gönderemezsin.","headers":[],"rows":[]}],"tasks":["Sekiz mesajın her biri için: şimdi yap / zamanla / delege et / beklet ve açıklama iste kararını yaz.","İlk 15 dakikayı ve sonraki üç saatlik takvimi oluştur; bağımlılıkları göster.","Müşteriye veriyi beklerken göndereceğin en fazla 80 kelimelik ara yanıtı yaz.","M8 için güvenli ve işin ilerlemesini sağlayan yanıtı hazırla."],"numbers":[],"rubric":[{"name":"Risk ve son tarih ayrımı","evidence":"Güvenlik riskini ele alır; yönetici unvanını tek öncelik ölçütü yapmaz."},{"name":"Bağımlılık ve takvim","evidence":"09.45, 10.30 ve 11.00 yükümlülüklerini 09.50 veri bağımlılığıyla birlikte planlar."},{"name":"Delegasyon","evidence":"Sahip, çıktı ve dönüş saatini yazar; bordro onayını yetkisiz kişiye vermez."},{"name":"Bilgi güvenliği","evidence":"Ham personel dosyasını kişisel e-postaya göndermek yerine iş ihtiyacını ve onaylı kanalı netleştirir."},{"name":"Paydaş iletişimi","evidence":"Biten, bekleyen ve devredilen işi açıkça bildirir; doğrulanmamış söz vermez."}],"update":{"title":"Tek kişi, yeni çatışma","text":"09.35’te bordro uzmanı kritik düzeltme için sana 20 dakika gerektiğini ve 10.00’da sistemi kapatacaklarını söylüyor. Yönetim slaytının son kontrolü de 10 dakika istiyor. Aynı zaman aralığında ikisini yapamazsın. Neyi teyit eder, hangi beklentiyi nasıl değiştirirsin?","reference":"Son tarihlerin değişebilirliğini ve bordro etkisini hemen teyit et. Slayt kontrolü uygun bir kişiye devredilebilir veya toplantıya geç/eksik teslim mutabakatı istenebilir. Yetkili bordro onayını başkasına bırakmak çözüm değildir. Tek bir doğru takvim yok; kısıtlarla tutarlı gerekçe aranır."},"solution":["09.00’da tesis sorumlusuna riskin yerini bildirip güvenli geçiş önlemini teyit et; işi kendin tamir etmeye çalışma. Resepsiyon ve satın alma devirlerini erken yap.","Örnek: 09.10–09.40 slayt, 09.40–09.50 kontrol/buffer, 09.50–10.10 müşteri yanıtı, 10.15–10.30 bordro onayı. Teyit ve koordinasyon süresini ayrıca ayır. Bu tek geçerli sıra değildir.","M6 günün ikinci yarısına planlanabilir. M8’de iş ihtiyacı sorulup yetkili erişim ve onaylı paylaşım yolu önerilir."],"pitfalls":["M1’i yalnız 15 dakikalık bir iş diye düşük önceliğe koymak.","Müşteriye analistin verisi gelmeden kesin neden açıklamak.","İşi delege edip takip ve geri dönüş saatini yazmamak."],"questions":["Hangi işi delege ettiğinde sorumluluğun devam eder?","Yönetim sunumunun süresi iki katına çıkarsa neyi değiştirirsin?"],"version":"1.0.0","candidateFile":"/cases/packs/gelen-kutusu-aday.md"},{"id":"geri-bildirim","title":"Yüksek çıktı, artan hata","level":1,"kind":"Yönetim görüşmesi","minutes":35,"roles":["lead","graduate"],"skills":["Geri bildirim","Dinleme","Performans bağlamı"],"brief":"Ekip liderisin. Arda’nın üretimi hedefi aşıyor; buna karşılık yeniden işlem gerektiren dosyalar artmış. Arda “ekibi ben taşıyorum, hata konuşmak haksızlık” diyor. 15 dakikalık gelişim görüşmesine hazırlanacaksın.","mandate":"Somut veriye dayalı bir görüşme açılışı, araştırma soruları, ortak hedef ve takip planı üret. Kişilik, niyet veya sağlık yorumu yapma.","docs":[{"title":"İki haftalık kayıt","text":"Dosyalar aynı kabul tanımıyla sayılmıştır; zorluk dağılımı ve hata ağırlığı henüz ayrıştırılmadı. Hedef hata oranı en çok %4. Bir dosyada birden fazla hata olsa bile dosya bir kez sayılır.","headers":["Dönem","Planlanan dosya","Tamamlanan dosya","Yeniden işlem gereken dosya"],"rows":[["Önceki hafta",100,100,5],["Son hafta",100,120,10]],"file":"/cases/packs/geri-bildirim-1.csv"},{"title":"Çalışanın notu","text":"“Son hafta iki acil iş bana aktarıldı. Kontrol listesindeki yeni alanı öğrendiğimi sanıyordum. Yardım istediğimde herkes yoğundu.” Son hafta ayrıca iki saat yeni bir arkadaşına destek verdiğini söylüyor; bu süre henüz iş kaydında doğrulanmadı.","headers":[],"rows":[]},{"title":"Yöneticinin hareket alanı","text":"İlk iki gün beş dosyalık ortak örnek incelemesi ve kısa kontrol desteği ayarlayabilirsin. Hata oranını düşürmek için kabul standardını gevşetemezsin. Geri bildirimin amacı disiplin hükmü vermek değil, nedenleri ve uygulanabilir desteği netleştirmektir.","headers":[],"rows":[]}],"tasks":["Olumlu katkıyı ve kalite sorununu birlikte içeren ilk 90 saniyelik konuşmayı yaz.","En az dört açık soru hazırla; veriyle henüz bilmediğin noktaları ayır.","İki haftalık bir gelişim anlaşması kur: davranış, destek, ölçüt ve kontrol günü.","Arda savunmaya geçerse söyleyeceğin kısa yanıtı ve görüşmeye dönüş sorusunu yaz."],"numbers":[{"id":"hata","label":"Son haftanın yeniden işlem oranı","value":8.333333333333334,"unit":"%","tolerance":0.06,"why":"10/120 × 100 = %8,33. Hedefin 4,33 yüzde puan üzerinde. Önceki hafta %5; adet kadar payda da önemlidir."}],"rubric":[{"name":"Somut ve dengeli açılış","evidence":"120 tamamlanan dosyayı ve 10 yeniden işlem dosyasını birlikte söyler; kişiyi özensiz diye etiketlemez."},{"name":"Nedeni araştırma","evidence":"İş zorluğu, yeni alan, acil yük ve destek iddiasını sorar; hiçbirini peşinen gerçek veya bahane ilan etmez."},{"name":"Destek ve hesap verebilirlik","evidence":"Kontrol standardını korurken ortak inceleme, yardım kanalı ve kişinin kendi adımını netleştirir."},{"name":"Takip","evidence":"Örneklem ve dönem tanımıyla hata oranını izler; kısa dönem düşüşünü tek başına kalıcı gelişim saymaz."}],"update":{"title":"Çalışan görüşe itiraz ediyor","text":"Arda, “10 dosyanın altısında talep sonradan değişti; bunları hata saymanız yanlış” diyor. Görüşmenin kalanını ve ölçüt incelemesini nasıl yönetirsin?","reference":"Hata tanımını ve altı dosyayı aynı ölçütle yeniden incele; veriyi doğrulamadan hata sayısını dörde indirme. Geçmiş kaydı değiştirme gerekçesini görünür tut; müşteri kapsam değişikliği ile işlem hatasını ayrı sınıflandır. Kişinin sözünü otomatik reddetmek de otomatik kabul etmek de zayıftır."},"solution":["Örnek açılış: “Bu hafta 120 dosya tamamlaman önemli bir katkı. Aynı dönemde 10 dosya yeniden işlem gördü. Hem iş yükünü hem bu dosyalarda ne olduğunu anlamak istiyorum.”","Önce beş dosyada yeni kontrol alanının nasıl uygulandığını birlikte incele. Yardım ve iş dağılımı ihtiyacını netleştir; kalite ölçütünü düşürme.","İki hafta aynı dosya/hata tanımıyla takip; ilk iki gün yakın destek ve belirli tarihte değerlendirme. Hedef %4 olsa bile az hacimde tek bir dosyanın oranı oynattığını not et."],"pitfalls":["Hedefi aşan üretim nedeniyle kalite sorununu tamamen görmezden gelmek.","Hata oranını 10/100 hesaplamak.","“Sen zaten böylesin” diyerek niyet veya kişilik atfetmek."],"questions":["Aynı sonuç daha zor iş karmasından geliyorsa değerlendirmeyi nasıl değiştirirsin?","Hedef tutmazsa desteğin mi, beklentinin mi değişmesi gerektiğine nasıl karar verirsin?"],"version":"1.0.0","candidateFile":"/cases/packs/geri-bildirim-aday.md"},{"id":"butce-sapmasi","title":"Bütçe aşıldı: neden ve kimin kontrolünde?","level":2,"kind":"Veri analizi","minutes":45,"roles":["analyst","operations","custom"],"skills":["Sapma analizi","Esnek bütçe","Maliyet"],"brief":"Bir hizmet merkezinin aylık maliyeti bütçeyi 15.000 TL aştı. Finans hacim artışını, operasyon ise satın alma fiyatını işaret ediyor. Analist olarak farkı ayrıştırıp sonraki ay için karar notu hazırlayacaksın.","mandate":"Hacim, birim değişken maliyet ve sabit gider farklarını ayrı göster. Hesap bileşenini kişisel sorumluluk veya kontrol edilebilirlik kanıtı gibi sunma.","docs":[{"title":"Bütçe ve gerçekleşen","text":"Birimler eşdeğer hizmet paketidir. Değişken maliyet hacimle doğrusal varsayılır. Vergi ve finansman etkisi yoktur.","headers":["Kalem","Bütçe","Gerçekleşen"],"rows":[["Hacim (paket)",10000,12000],["Değişken maliyet (TL/paket)",4,4.5],["Sabit gider (TL)",18000,19000]],"file":"/cases/packs/butce-sapmasi-1.csv"},{"title":"Sonraki ay seçenekleri","text":"14.000 paket bekleniyor. İçeride değişken maliyet 4,50 TL/paket, sabit gider 19.000 TL. Dış kaynak teklifi 4,30 TL/paket ve 22.000 TL sabit gider. İki seçenekte hizmet standardının eşit olduğu henüz doğrulanmadı; sözleşme ve geçiş maliyeti verilmedi.","headers":[],"rows":[]},{"title":"Yönetim sorusu","text":"“15.000 TL sapmanın tamamını operasyon yöneticisinin hedefinden düşelim mi?” Satın alma fiyatının hangi nedenle değiştiği, hacim onayının kimde olduğu ve sabit giderdeki artışın niteliği henüz belgelenmedi.","headers":[],"rows":[]}],"tasks":["Statik bütçeyi ve gerçekleşen maliyeti hesapla; farkı üç bileşene ayır.","Gerçek hacim için esnek bütçeyi oluştur ve esnek bütçe farkını açıklığa kavuştur.","14.000 paket için iki seçeneği karşılaştır; eksik maliyet ve hizmet bilgilerini listele.","Finans ve operasyona en fazla 200 kelimelik tarafsız bir yönetici notu yaz."],"numbers":[{"id":"sapma","label":"Toplam olumsuz maliyet sapması","value":15000,"unit":"TL","tolerance":0.1,"why":"Bütçe: 10.000×4+18.000=58.000. Gerçek:12.000×4,5+19.000=73.000. Fark15.000."},{"id":"hacim","label":"Hacim bileşeni","value":8000,"unit":"TL","tolerance":0.1,"why":"(12.000−10.000)×4 =8.000. Fiyat bileşeni12.000×(4,5−4)=6.000; sabit fark1.000; toplam15.000."},{"id":"esnek","label":"Esnek bütçe","value":66000,"unit":"TL","tolerance":0.1,"why":"12.000×4+18.000=66.000; gerçekleşenle fark7.000."},{"id":"ic","label":"Sonraki ay iç kaynak toplamı","value":82000,"unit":"TL","tolerance":0.1,"why":"14.000×4,5+19.000=82.000. Dış kaynak14.000×4,3+22.000=82.200; yalnız verilen maliyetlerle iç kaynak200 TL düşük."}],"rubric":[{"name":"Ayrıştırma","evidence":"Hacmi bütçe fiyatıyla, fiyat farkını gerçek hacimle hesaplar; bileşenler toplam farka bağlanır."},{"name":"Karşılaştırma tabanı","evidence":"Esnek bütçe ile statik bütçenin farklı sorulara yanıt verdiğini açıklar."},{"name":"Kontrol ve sorumluluk","evidence":"Fiyat/sabit farkını otomatik kişisel kusur saymaz; karar yetkisi ve neden verisini ister."},{"name":"Seçenek analizi","evidence":"200 TL farkın yanında geçiş maliyeti ve hizmet eşdeğerliğini araştırır."},{"name":"Yönetici notu","evidence":"Hesabı, varsayımı, eksik bilgiyi ve önerilen kararı ayrı verir."}],"update":{"title":"Teklif değişti","text":"Dış kaynak ilk ay için ayrıca 6.000 TL geçiş bedeli istiyor. Beklenen hacim 18.000’e çıktı. İç kaynak kapasitesi ayda en fazla 16.000; fazla paket için içeride çözüm henüz tanımlı değil. Fiyat kıyasını neden tek başına kullanamazsın?","reference":"Dış kaynak ilk ay18.000×4,3+22.000+6.000=105.400 TL. İç kaynak18.000×4,5+19.000=100.000 TL görünen tutardır ama16.000 kapasite sınırını ihlal eder; uygulanabilir alternatif değildir. Karma çözüm maliyeti ve kapasitesi tanımlanmadan en ucuz seçenek ilan edilmez."},"solution":["15.000 TL farkın8.000’i hacim,6.000’i birim maliyet,1.000’i sabit giderden gelir. Ayrıştırma hangi yöneticinin sorumlu olduğunu tek başına söylemez.","Gerçek hacimde beklenen66.000 TL ile73.000 TL arasındaki7.000 TL ayrıca araştırılır.","14.000 pakette verilen varsayımlarla iç kaynak82.000, dış kaynak82.200 TL. Hizmet düzeyi, kapasite ve geçiş maliyeti doğrulanmadan son karar verilmez."],"pitfalls":["Bütün farkı birim maliyet artışına bağlamak.","Fiyat farkını bütçe hacmiyle hesaplayıp bileşen toplamını tutturamamak.","Kapasiteyi aşan seçeneği uygulanabilir ve ucuz saymak."],"questions":["Hacimle doğrusal olmayan maliyetlerde bu model nasıl değişir?","Esnek bütçe farkının tamamı kontrol edilebilir midir?"],"version":"1.0.0","candidateFile":"/cases/packs/butce-sapmasi-aday.md"},{"id":"kampanya-karari","title":"Ciro kazandıran kampanya para kazandırıyor mu?","level":2,"kind":"Veri analizi","minutes":45,"roles":["analyst","custom","graduate"],"skills":["Birim ekonomi","Ticari karar","Belirsizlik"],"brief":"Meral E-Ticaret, üç reklam kanalının bütçesini yeniden dağıtacak. Pazarlama en yüksek ciroya sahip kanala ek bütçe istiyor. Sen katkı ve ölçüm sınırlılıklarını içeren karar önerisi hazırlayacaksın.","mandate":"Verilen brüt marjlar ürün maliyeti sonrasıdır; reklam gideri ayrıca düşülür. Bunun şirket net kârı olmadığını belirt. Ek bütçe performansının geçmiş ortalamayla aynı kalacağı varsayılmamalı.","docs":[{"title":"30 günlük olgunlaşmış kampanya kohortu","text":"Her sipariş tek kanala atanmıştır. Sipariş tutarları iade öncesidir. İade bilgisi bu ilk tabloda yoktur. Organik kampanya gideri içerik üretimini içerir.","headers":["Kanal","Kampanya gideri TL","Potansiyel müşteri","Sipariş","Ortalama sepet TL","Brüt marj %"],"rows":[["İçerik",10000,500,50,1000,40],["Ücretli reklam",30000,1200,120,600,25],["İş ortaklığı",12000,300,30,1200,35]],"file":"/cases/packs/kampanya-karari-1.csv"},{"title":"Bütçe toplantısı","text":"Bir sonraki dönem ek15.000 TL var. İçerik üretim ekibi en fazla%20 hacim artışını destekleyebileceğini söylüyor; diğer kanalların doygunluk ve artımlılık bilgisi yok. Ücretli reklam ekibi “72.000 TL ciro getirdik; en iyi biziz” diyor.","headers":[],"rows":[]},{"title":"Ölçüm notu","text":"Kampanya katkısı = sipariş × ortalama sepet × brüt marj − kampanya gideri. Sabit işletme giderleri, finansman, müşteri yaşam boyu değeri ve kanallar arası etkileşim dahil değildir. Bu veri tek başına nedensel reklam etkisini kanıtlamaz.","headers":[],"rows":[]}],"tasks":["Kanal bazında ciro, reklam sonrası katkı ve sipariş başına kampanya giderini hesapla.","En yüksek cironun neden en yüksek katkı olmadığını göster.","Ek15.000 TL için kontrollü deneme öner: bütçe sınırı, başarı ölçütü, durdurma koşulu ve karşılaştırma.","Pazarlama ekibine kararını anlatan en fazla dört slaytlık içerik iskeleti yaz."],"numbers":[{"id":"ucretli","label":"Ücretli reklam kanalının katkısı","value":-12000,"unit":"TL","tolerance":0.1,"why":"120×600×0,25−30.000=−12.000."},{"id":"toplam","label":"Üç kanalın toplam katkısı","value":-1400,"unit":"TL","tolerance":0.1,"why":"İçerik10.000; ücretli−12.000; ortaklık600; toplam−1.400."},{"id":"cpa","label":"İş ortaklığında sipariş başına kampanya gideri","value":400,"unit":"TL/sipariş","tolerance":0.1,"why":"12.000/30=400. İçerik200, ücretli250. Daha düşük edinim gideri de tek başına daha iyi müşteri kanıtı değildir."}],"rubric":[{"name":"Katkı hesabı","evidence":"Brüt marjı ciroya uygular, reklam giderini yalnız bir kez düşer; negatif katkıyı gösterir."},{"name":"Ölçüm sınırları","evidence":"ROAS/ciro ile katkıyı, atıf ile artımlı etkiyi ayırır."},{"name":"Kaynak ve kapasite","evidence":"Ek bütçenin otomatik aynı dönüşü getireceğini varsaymaz; içerik kapasite sınırını işler."},{"name":"Deneme tasarımı","evidence":"Bütçe, dönem, ölçüt, durdurma ve karşılaştırma koşullarını netleştirir."},{"name":"Ticari iletişim","evidence":"Ekibin katkısını küçümsemeden olumsuz birim ekonomiyi açıklar."}],"update":{"title":"İadeler görünür oldu","text":"Ücretli reklam siparişlerinin%20’si iade edildi. Basitleştirilmiş varsayım: bu siparişlerin gelir ve ürün brüt katkısı tamamen iptal oluyor; kampanya gideri değişmiyor ve ek iade maliyeti yok. Kanal katkısı ne olur? Gerçek hayatta hangi ek kalemleri isterdin?","reference":"18.000 TL brüt katkı ×0,80−30.000 =−15.600 TL. Gerçekte ürün geri kazanımı, taşıma, işlem gideri ve kohort olgunluğu ayrıca incelenir."},"solution":["Ciro:50.000 /72.000 /36.000 TL. Brüt katkı:20.000 /18.000 /12.600 TL. Reklam sonrası katkı:10.000 /−12.000 /600 TL.","Geçmiş ortalamaya göre içerik avantajlı görünür; fakat kapasite ve artımlı etki belirsizdir. Bütçeyi tek kanala koşulsuz aktarmak yerine sınırları belli bir deneme gerekçelendirilebilir.","Müşteri kalitesi, tekrar satın alma ve iadeler yeni sorulardır; veri yokken bu etkileri uydurup zararı telafi etmiş sayma."],"pitfalls":["Ciroyu kâr olarak adlandırmak.","Marjı reklam giderine uygulamak.","Ek bütçenin aynı ortalama dönüşle çalışacağını garanti etmek."],"questions":["Kontrol grubu yoksa kampanyanın gerçek etkisi için ne söyleyebilirsin?","Kısa vadeli katkı ile müşteri yaşam boyu değerini nasıl birlikte incelersin?"],"version":"1.0.0","candidateFile":"/cases/packs/kampanya-karari-aday.md"},{"id":"aday-hunisi","title":"Çok başvuru, az kabul","level":2,"kind":"Veri analizi","minutes":45,"roles":["analyst","custom","lead"],"skills":["Süreç analizi","Dönüşüm","Adil karşılaştırma"],"brief":"Ladin Teknoloji, aynı uzmanlık rolü için üç aday kaynağını kullandı. İK başvuru sayısını artırmak istiyor; işe alım yöneticisi teklif kabulünün düştüğünü düşünüyor. Süreç darboğazı ve takip planı çıkaracaksın.","mandate":"Aynı tamamlanmış aday kohortunu karşılaştır. Kaynak verisinden kişilerin kalitesini veya işe uygunluğunu çıkarma. Teklif kabulü ile işe başlama ve iş başarısını ayır.","docs":[{"title":"Tamamlanmış kohort","text":"Tüm adayların süreç kararı tamamlandı; kaynaklar çakışmıyor. Bir kişi her aşamada en fazla bir kez sayıldı. Teklifler bir alt küme, kabuller tekliflerin alt kümesidir.","headers":["Kaynak","Başvuru","Ön görüşme","Teknik görüşme","Teklif","Kabul","Kaynak gideri TL"],"rows":[["Çalışan önerisi",100,40,20,10,8,8000],["İş ilanı",400,100,30,12,6,18000],["Kampüs",200,80,40,20,10,10000]],"file":"/cases/packs/aday-hunisi-1.csv"},{"title":"Eksik bilgiler","text":"Ücret beklentisi, teklif koşulları, aday kıdemi, süreçte bekleme süreleri, işe başlayan sayısı ve90 günlük izlem verisi yok. Gider yalnız kaynak edinim gideridir; görüşmeci zamanı ve diğer işe alım maliyetleri dahil değildir.","headers":[],"rows":[]},{"title":"Karar ortamı","text":"Sonraki dönem aynı rol için24 teklif kabulü hedefleniyor. Yönetim çalışan önerisine bütçeyi üç katına çıkarmayı düşünüyor; bu kanalın havuzu ve ölçeklenebilirliği bilinmiyor. Karşılaştırılabilir görev kapsamı ve ücret bandını ayrıca doğrulamalısın.","headers":[],"rows":[]}],"tasks":["Kaynak bazında teklif kabul oranını ve kabul başına kaynak giderini hesapla.","En fazla başvurunun hangi darboğazı gizleyebildiğini açıklayan bir süreç özeti yaz.","İlk iki haftada toplayacağın ek verileri ve tanımlarını belirle.","Kaynak bütçesi için kesin dağılım uydurmadan kontrollü bir öneri sun."],"numbers":[{"id":"genel","label":"Toplam teklif kabul oranı","value":57.142857142857146,"unit":"%","tolerance":0.06,"why":"Kabul8+6+10=24; teklif10+12+20=42;24/42=%57,14."},{"id":"ilan","label":"İş ilanı kaynağında kabul başına kaynak gideri","value":3000,"unit":"TL/kabul","tolerance":0.1,"why":"18.000/6=3.000. Çalışan önerisi1.000, kampüs1.000 TL/kabul."},{"id":"oneri","label":"Çalışan önerisinde teklif kabul oranı","value":80,"unit":"%","tolerance":0.05,"why":"8/10×100=%80. Küçük hacim ve aday karması nedeniyle evrensel üstünlük göstermez."}],"rubric":[{"name":"Aşama paydası","evidence":"Teklif kabulünü başvuruya değil teklife böler; toplamda ağırlıklı hesap yapar."},{"name":"Süreç teşhisi","evidence":"Ön görüşme/teknik/teklif/kabul geçişlerini ayrı inceler; tek bir aşamayı peşinen suçlamaz."},{"name":"Karşılaştırılabilirlik","evidence":"Rol, kıdem, ücret ve bekleme farklarını ister; kaynak etiketini aday kalitesi saymaz."},{"name":"Maliyet kapsamı","evidence":"Kaynak giderini toplam işe alım maliyeti veya işe başlayan başı maliyet olarak sunmaz."},{"name":"Ölçek ve takip","evidence":"Öneri kanalını üç kat büyütmenin aynı oranı koruyacağını varsaymaz; sınırlı deneme ve izlem önerir."}],"update":{"title":"Ret nedenleri geldi","text":"İş ilanı kaynağındaki altı reddin dördü ücret, ikisi uzun süreç gerekçesiyle açıklanmış. Kampüs kaynağında10 kabulün yalnız yedisi işe başlamış; diğer iki kanalın işe başlama verisi henüz yok. Bütçe önerini nasıl güncellersin?","reference":"İş ilanında ücret ve bekleme süreci araştırılabilir; açıklamalar nedensel deney değildir. Kampüs için10.000/7≈1.428,57 TL/başlayan hesaplanabilir, fakat diğer kanallarla kabul başı maliyeti karşılaştırarak sıralama yapılamaz. Eşit sonlanım verisi gerekir."},"solution":["Toplam24 kabul/42 teklif=%57,14. Öneri%80; ilan%50; kampüs%50. Kaynak gideri/kabul1.000/3.000/1.000 TL.","İlan kaynağı hacimli ama başvurudan teknik görüşmeye400→30 düşüyor. Bunun düşük aday kalitesi mi, yanlış hedefleme mi, koşullar mı olduğunu bu tablo söylemez.","Aynı rol/ücret/kıdem ve tamamlanmış kohortlarla aşama süresi, ret nedeni, başlangıç ve izlem verisi topla. Bütçe değişimini kapasite ve adil değerlendirme koşullarıyla dene."],"pitfalls":["24 kabulü700 başvuruya bölüp teklif kabul oranı demek.","Çalışan önerisinden gelen herkesin daha iyi çalışan olacağını söylemek.","Kabul sayısını işe başlayan sayısı gibi kullanmak."],"questions":["Açık süreçteki adayları dahil etseydin oranlar nasıl yanıltabilirdi?","Kaynak ve aday karması etkilerini nasıl ayırmaya çalışırdın?"],"version":"1.0.0","candidateFile":"/cases/packs/aday-hunisi-aday.md"},{"id":"proje-kisitlari","title":"Takvimde paralel, gerçekte aynı kişi","level":2,"kind":"Karar ve sunum","minutes":45,"roles":["analyst","lead","custom"],"skills":["Bağımlılık","Kaynak planlama","Kapsam yönetimi"],"brief":"Bir iç raporlama aracı için yönetim dokuz iş günlük teslim sözü verdi. Görev ağı bu süreyi destekliyor gibi görünüyor; ekipte ise tek geliştirici var. Proje sorumlusu olarak uygulanabilir plan hazırlayacaksın.","mandate":"Önce yalnız bağımlılıkları, sonra kaynak kısıtını dikkate al. Süreler tam iş günüdür; görevler bölünemez. Aynı kişi iki görevi eşzamanlı yapamaz. Teslim tarihi veya kapsam değişikliği için paydaş mutabakatı gerekir.","docs":[{"title":"Görev ağı","text":"Gün1 başlangıçtır. Örneğin iki günlük A gün1–2 sürer; ona bağlı iş en erken gün3 başlar.","headers":["ID","Görev","Süre gün","Öncül","Kaynak"],"rows":[["A","Gereksinimi netleştir",2,"Yok","Analist"],["B","Veri bağlantısı",3,"A","Geliştirici"],["C","Rapor ekranı",4,"A","Aynı geliştirici"],["D","Kabul testi",2,"B ve C","Test uzmanı"],["E","Canlıya geçiş onayı",1,"D","Ürün sahibi"]],"file":"/cases/packs/proje-kisitlari-1.csv"},{"title":"Seçenekler","text":"Dış ekip C’yi dört günde, A biter bitmez ve B ile paralel tamamlayabiliyor; bedel12.000 TL. Dış kaynak erişimi ve teslim kalitesi önceden onaylanmalı. İç geliştiriciye fazla çalışma verilirse B+C toplamı yalnız bir gün kısalıyor; sürdürülebilirlik ve onay gerekir.","headers":[],"rows":[]},{"title":"Kapsam sınırı","text":"B ve C mevcut teslimin ikisi de zorunlu parçası. Birini keserek kısmi teslim yapılabilir ama kullanıcı ve ürün sahibi kabulü olmadan “aynı ürün teslim edildi” denemez.","headers":[],"rows":[]}],"tasks":["Kaynaklar sınırsızken en erken bitişi ve kritik yolu göster.","Tek geliştiriciyle uygulanabilir başlangıç–bitiş takvimi çıkar.","İç plan, dış kaynak ve onaylı kapsam daraltmayı maliyet/tarih/risk açısından karşılaştır.","Yönetim için karar talebini ve kabul testinde korunacak ölçütleri yaz."],"numbers":[{"id":"ag","label":"Yalnız bağımlılıklarla en kısa süre","value":9,"unit":"iş günü","tolerance":0,"why":"A2 + max(B3,C4) + D2 + E1 =9; kritik yol A–C–D–E."},{"id":"kaynak","label":"Tek geliştiriciyle en kısa süre","value":12,"unit":"iş günü","tolerance":0,"why":"A2 + B3 + C4 + D2 + E1 =12. B/C sırası değişebilir; toplam değişmez."},{"id":"dis","label":"C dış ekipte paralel olursa süre","value":9,"unit":"iş günü","tolerance":0,"why":"A sonrası B3 ve dış C4 paralel; test ve onayla toplam9. Erişim/kalite onayı varsayımı kritiktir."}],"rubric":[{"name":"Ağ ve kaynak ayrımı","evidence":"Dokuz günlük ağ süresini tek geliştiriciyle uygulanabilir planla karıştırmaz."},{"name":"Tutarlı takvim","evidence":"Öncülleri, tam günleri ve tek kaynak kullanımını doğru uygular."},{"name":"Alternatiflerin açıklığı","evidence":"Tarih, bedel, kapsam ve onay gereğini karşılaştırır; gizli fazla mesaiyi varsaymaz."},{"name":"Kalite ve kabul","evidence":"Testi kaldırmaz; kısmi teslim varsa değişen kabul tanımını görünür tutar."},{"name":"Karar iletişimi","evidence":"Sorun, seçenek, öneri, karar sahibi ve karar zamanını yazar."}],"update":{"title":"Test bulgusu","text":"Kabul testi kapsamına ek bir gün gerektiği doğrulandı. Dış ekip seçeneği hâlâ mevcut. Dokuz günlük taahhüt için hangi seçeneklerin artık yeterli olmadığını açıkla; “testi sonraya bırakma” önerisine yanıt ver.","reference":"İç kaynak13, paralel dış C10 iş günü olur. Dış kaynak tek başına dokuz günü artık sağlamaz. Testi kaldırmak aynı kabulü sağlamak değildir; yeni tarih, onaylı kapsam veya başka doğrulanmış kaynak/süre seçeneği için karar gerekir."},"solution":["A gün1–2; B gün3–5; C gün6–9; D gün10–11; E gün12 uygulanabilir örnektir. B/C ters sırada da olabilir.","12.000 TL dış kaynak ile9 gün, erişim ve kalite varsayımları sağlanırsa mümkün. Bu tutar yalnız tedarik bedelidir; iç koordinasyon maliyeti verilmedi.","Yönetimden seçenekleri ve kabul kapsamını görerek karar iste; takvimi sihirli biçimde kısaltma."],"pitfalls":["Tek geliştiriciyi B ve C’ye aynı günlerde yazmak.","Testi sıfırlayarak teslimi kurtarmak.","Kısmi teslimi tam kapsamlı teslim gibi raporlamak."],"questions":["Kritik yol ile kritik kaynak her zaman aynı şey midir?","Dış ekibin başlaması iki gün gecikirse planı nasıl güncellersin?"],"version":"1.0.0","candidateFile":"/cases/packs/proje-kisitlari-aday.md"},{"id":"parti-kalitesi","title":"Şüpheli parti, bekleyen müşteriler","level":3,"kind":"Karar ve sunum","minutes":60,"roles":["operations","lead","analyst"],"skills":["Risk yönetimi","İzlenebilirlik","Paydaş kararı"],"brief":"Bir tüketim ürünü partisinde kalite sorunu şüphesi oluştu. Sevkiyat baskısı yüksek; küçük örneklemden kesin sonuç çıkarılamıyor. Operasyon yöneticisi olarak izlenebilirlik, müşteri etkisi ve karar yetkisini birlikte yöneteceksin.","mandate":"Bu bir genel operasyon simülasyonudur; ürünün düzenleyici sınıfına özgü geri çağırma prosedürü verilmedi. Teknik kalite kararını kendin uydurma. Önlem, izlenebilirlik, yetkili değerlendirme ve iletişim planı oluştur.","docs":[{"title":"Parti ve örneklem","text":"Sevk edilmiş ve depoda bulunan miktarlar birbirini dışlar; toplamı parti toplamıdır. Örnek sonuçları bağımsız rastgeleliğin veya kabul planının kanıtı değildir.","headers":["Parti","Toplam adet","Sevk edilmiş","Depoda","İncelenen numune","Uygunsuz numune"],"rows":[["A",1000,600,400,50,5],["B",800,200,600,40,0]],"file":"/cases/packs/parti-kalitesi-1.csv"},{"title":"Bekleyen sipariş tahsisi","text":"Aşağıdaki miktarlar depodaki stokların alt kümesidir; stok toplamına tekrar eklenmez. B’yi ikame olarak kullanmak kalite ve ürün eşdeğerliği onayı gerektirir.","headers":["Sipariş","A tahsis","B tahsis","Çıkış hedefi"],"rows":[["O1",100,200,"Bugün12.00"],["O2",200,0,"Bugün14.00"],["O3",0,100,"Bugün16.00"]],"file":"/cases/packs/parti-kalitesi-2.csv"},{"title":"Yetki ve zaman","text":"Şüpheli A stoğunu ayırabilir, sevkiyatını geçici durdurabilir ve iz sürme listesini hazırlatabilirsin. Kullanım/serbest bırakma kararı kalite sorumlusunda. İlk teknik değerlendirme dört saat içinde gelebilir, kesin süre değil. Müşteriye “ürün güvenlidir” veya “mutlaka kusurludur” diyemezsin. Ticari taahhüt değişiklikleri satışla koordine edilir.","headers":[],"rows":[]}],"tasks":["İlk30 dakika, ilk dört saat ve gün sonu için karar/eylem planı yaz.","Etkilenen sevk edilmiş miktarı, ayrılacak depo stoğunu ve onay verilirse gerekli B ikamesini hesapla.","B’de sıfır uygunsuz numunenin neyi kanıtlamadığını ve hangi bilgiyi isteyeceğini açıkla.","O1 müşterisine gönderilecek ara iletişim taslağını ve yönetim karar notunu hazırla.","Serbest bırakma, durdurmayı sürdürme ve kapsamı genişletme için yetkili karar kapılarını belirt."],"numbers":[{"id":"sevk","label":"A partisinden iz sürülmesi gereken sevk edilmiş miktar","value":600,"unit":"adet","tolerance":0,"why":"A sevk edilmiş600; depodaki400 ile karıştırılmaz. Bu miktar tümünün kusurlu olduğu iddiası değildir."},{"id":"karantina","label":"A partisinde ayrılacak mevcut depo stoğu","value":400,"unit":"adet","tolerance":0,"why":"Tahsisli300 A, depodaki400’ün içindedir; karantinaya300 eklenip700 sayılmaz."},{"id":"ikame","label":"Bekleyen siparişlerde A yerine gereken B miktarı","value":300,"unit":"adet","tolerance":0,"why":"O1’de100+O2’de200=300 ikame. Mevcut B tahsisi300; toplam ihtiyaç600, B stoğu600. Serbest bırakma ve eşdeğerlik onayı olmadan sevk edilmez."}],"rubric":[{"name":"Önlem ve yetki","evidence":"Şüpheli stoğu ayırır, kalite kararını yetkiliye taşır; satış baskısıyla onaysız sevk etmez."},{"name":"İzlenebilirlik","evidence":"Parti, sipariş, müşteri ve miktar listesini ayrı tutar; tahsisleri çift saymaz."},{"name":"Örneklem yorumu","evidence":"0/40 sonucunu sıfır gerçek risk veya kesin güvenlik kanıtı olarak sunmaz."},{"name":"Alternatif ve koşul","evidence":"B ikamesini stok, eşdeğerlik ve kalite onayı koşullarıyla önerir."},{"name":"Müşteri iletişimi","evidence":"Doğrulanmış bilgi, belirsizlik, sonraki güncelleme zamanı ve sorumlu kişiyi ayırır."},{"name":"Karar kaydı","evidence":"Kim, hangi veriyle, ne zaman karar verecek; kapsam değişirse hangi kayıtlar güncellenecek açıklar."}],"update":{"title":"İkame kısıtı","text":"B partisinin100 adedinin başka müşteriye kesin tahsisli olduğu, ilk listede yer almadığı bulundu. Bu stok bu üç siparişe kullanılamaz. Tüm bekleyen siparişleri B ile tamamlamak mümkün mü? Müşteriler arasında dağıtımı nasıl gerekçelendirirsin?","reference":"Kullanılabilir B500; ihtiyaç600 →100 adet açık. Güvenlik ve teknik onayı aşmadan kısmi teslim/yeniden tarih seçenekleri gerekir. Öncelik; sözleşme, etki, son tarih ve yetkili ticari kararla belirlenir, kişisel yakınlıkla değil."},"solution":["A sevkiyatını geçici durdur;400 mevcut adedi ayır ve600 sevk adedinin alıcılarını izlenebilir kayıtla çıkar. Şüpheli miktarla kesin kusurlu miktarı ayır.","Bekleyen300 A için B ikamesi ancak onayla mümkündür. B’de600 toplam stok, mevcut300 B tahsisi ve ek300 ikameyle tam kullanılır; tampon yoktur.","Teknik kabul planı, numune seçimi, hata türü, lot ilişkisi ve ürün sınıfı istenir. Yetkili prosedür olmadan ne kesin güvenlik ne mevzuat gereği geri çağırma kararı uydurulur."],"pitfalls":["A’daki%10 numune oranını600 sevke uygulayıp kesin60 kusurlu ilan etmek.","B’de0/40 sonucundan kesin güvenlik çıkarmak.","Tahsisli miktarı depodaki stok üzerine eklemek."],"questions":["Kalite sorumlusu dört saatte yanıt veremezse müşteriye ne söylersin?","Partilerin ortak hammaddesi olduğu ortaya çıkarsa hangi kapsam değişir?"],"version":"1.0.0","candidateFile":"/cases/packs/parti-kalitesi-aday.md"},{"id":"yatirim-kapasitesi","title":"Otomasyon: kapasite kazancı mı, nakit tasarrufu mu?","level":3,"kind":"Karar ve sunum","minutes":60,"roles":["operations","analyst","lead"],"skills":["Yatırım karşılaştırma","Duyarlılık","Fayda doğrulama"],"brief":"Bir işlem merkezinde iki otomasyon seçeneği var. Sunumlar işçilik saati kazancını “nakit tasarruf” olarak gösteriyor; personel sayısı ise değişmeyecek. Yönetim senden karşılaştırmalı öneri istiyor.","mandate":"Önce verilen tam ekonomik değer varsayımını hesapla, sonra gerçekleşebilirlik koşullarını araştır. Basit geri ödeme hesabıdır; indirgeme, vergi, finansman ve hurda değeri dahil değildir.","docs":[{"title":"Aylık baz ve teklifler","text":"İşlem hacmi12.000/ay, mevcut emek6 dk/işlem →1.200 saat/ay. Saat başı220 TL, yüklenmiş ekonomik maliyettir; tamamen önlenebilir nakit maliyet olduğu doğrulanmadı. Kazançlar birbirine alternatif, birlikte uygulanmaz.","headers":["Seçenek","Başlangıç yatırımı TL","Kazanılan saat/ay","Bakım TL/ay"],"rows":[["A",480000,400,12000],["B",300000,250,6000]],"file":"/cases/packs/yatirim-kapasitesi-1.csv"},{"title":"İnsan ve kapasite notu","text":"Personel sayısının azaltılması planlanmıyor. Ek kapasitenin başka işte kullanımı için doğrulanmış talep yok. Fazla mesai/taşeron azaltımı ve maliyet kalemlerinin nakit niteliği araştırılmalı. Saat tasarrufu otomatik bütçe düşüşü sayılmaz.","headers":[],"rows":[]},{"title":"Karşılaştırma talebi","text":"Tam saat değerinin gerçekleştiği varsayımıyla aylık net fayda, basit geri ödeme ve12 aylık yatırım sonrası farkı göster. Ardından yalnız%50 saat değerinin gerçekleştiği senaryoyu incele. Kurulum duruşu ve eğitim maliyeti verilmedi; sıfır olduğunu varsaydığını saklama.","headers":[],"rows":[]}],"tasks":["Tam gerçekleşme varsayımıyla A/B aylık net faydasını ve basit geri ödeme süresini hesapla.","12 aylık net faydadan yatırımı düşerek alternatifleri karşılaştır; neden tek başına geri ödeme sırasının yeterli olmadığını açıkla.","%50 gerçekleşme senaryosunu ve en az iki başka duyarlılığı yaz.","Hangi faydayı, kimden ve nasıl doğrulamadan satın alma kararı önermeyeceğini belirt.","En fazla beş slaytlık yatırım karar sunumu iskeleti hazırla."],"numbers":[{"id":"netA","label":"Tam gerçekleşmede A aylık net ekonomik faydası","value":76000,"unit":"TL/ay","tolerance":0.1,"why":"400×220−12.000=76.000. Nakit tasarruf olarak doğrulanmış değildir."},{"id":"netB","label":"Tam gerçekleşmede B aylık net ekonomik faydası","value":49000,"unit":"TL/ay","tolerance":0.1,"why":"250×220−6.000=49.000."},{"id":"payA","label":"A basit geri ödeme süresi","value":6.315789473684211,"unit":"ay","tolerance":0.02,"why":"480.000/76.000≈6,32 ay. B≈6,12 ay."},{"id":"yarimA","label":"%50 gerçekleşmede A aylık net faydası","value":32000,"unit":"TL/ay","tolerance":0.1,"why":"400×0,50×220−12.000=32.000; geri ödeme15 ay. B21.500/ay ve≈13,95 ay."}],"rubric":[{"name":"Fayda niteliği","evidence":"Serbest kapasite, ekonomik değer ve önlenebilir nakit gideri ayırır."},{"name":"Hesap tutarlılığı","evidence":"Bakımı aylık faydadan düşer; yatırımın süre ile birimlerini tutarlı kullanır."},{"name":"Alternatifler","evidence":"B’nin daha kısa geri ödemesini A’nın daha yüksek12 aylık farkıyla birlikte inceler."},{"name":"Duyarlılık","evidence":"Gerçekleşme, hacim, kurulum ve bakım varsayımlarını değiştirir; faydaları çift saymaz."},{"name":"Uygulama ve doğrulama","evidence":"Pilot ölçümü, baz dönem, iş karması, duruş ve fayda sahibini tanımlar."},{"name":"Karar önerisi","evidence":"Belirsiz faydayı kesin kâr diye sunmadan koşullu karar ve sonraki bilgi ihtiyacını belirtir."}],"update":{"title":"Fayda sahibi itiraz ediyor","text":"Finans saat maliyetinin yalnız80 TL’sinin önlenebilir fazla mesai/taşeron gideri olduğunu doğruladı. Kalan140 TL nakit çıkışını azaltmıyor. Kazanılan saatlerin tamamı bu önlenebilir çalışmanın yerine geçerse net aylık nakit fayda ve geri ödeme nasıl değişir?","reference":"A:400×80−12.000=20.000 TL/ay →24 ay. B:250×80−6.000=14.000 TL/ay →≈21,43 ay. Saatlerin gerçekten bu çalışmanın yerine geçtiği ayrıca doğrulanmalı; aynı saati hem kapasite hem tam nakit fayda olarak toplama."},"solution":["Tam ekonomik değerle A76.000/B49.000 TL net/ay. Geri ödeme A6,32/B6,12 ay.12 aylık net fayda eksi yatırım A432.000/B288.000 TL.","%50 gerçekleşmede A32.000/B21.500 TL; geri ödeme15/13,95 ay. Bu sonuçlar doğrulanmış nakit tasarruf değildir.","İlk öneri koşullu pilot olabilir: aynı iş karmasında saat kazancını, duruşu, kaliteyi ve önlenebilir maliyeti ölç. Kapasitenin nasıl kullanılacağını fayda sahibiyle belgele."],"pitfalls":["Personel sayısı sabitken tüm yüklenmiş saat maliyetini nakit tasarruf saymak.","Saat kazancını işçilik giderine ek olarak tekrar kapasite geliri diye çift saymak.","En kısa geri ödemeyi tek karar ölçütü yapmak."],"questions":["Talep düşerse hangi faydalar daha çok etkilenir?","Pilot ölçümünde kalite kaybını nasıl hesaba katarsın?"],"version":"1.0.0","candidateFile":"/cases/packs/yatirim-kapasitesi-aday.md"},{"id":"ekip-yuku","title":"Ortalama dengeli, bir kişi taşmış","level":3,"kind":"Yönetim görüşmesi","minutes":55,"roles":["lead","operations","analyst"],"skills":["İş dağılımı","Adil karar","Delegasyon"],"brief":"Dört kişilik bir uzman ekibini yönetiyorsun. Toplam iş yükü haftalık kapasitenin altında görünüyor; Ece ise sürekli fazla çalışma ihtiyacı olduğunu söylüyor. İş dağılımı ve ekip görüşmesini yeniden düzenleyeceksin.","mandate":"Kişisel neden veya sağlık yorumu yapmadan sözleşmesel net kapasiteleri kullan. Bütün işleri herkes yapamıyor. Mentorluk/destek saatleri gerçek iş yüküdür, görünmez sayma.","docs":[{"title":"Haftalık iş yükü","text":"Kapasiteler molalar ve planlı izinler sonrası net saattir. Ana işler ve destek saatleri farklı işlerdir, birbirini içermez.","headers":["Kişi","Net kapasite saat","Ana iş saat","Mentorluk/destek saat"],"rows":[["Deniz",40,32,4],["Ece",40,44,0],["Can",32,24,4],["Mert",40,36,4]],"file":"/cases/packs/ekip-yuku-1.csv"},{"title":"Devredilebilir görev","text":"Ece’nin44 saatlik ana işinin içinde4 saatlik haftalık rapor vardır. Raporu Deniz veya Can yapabilir; Mert bu raporu yapamaz. Devir için gerekli bilgi paylaşımı raporun dört saatlik tahminine dahildir. İşin son tarihi korunmalı; Ece’den alıp başka kişinin yüküne ekle.","headers":[],"rows":[]},{"title":"Görüşme bağlamı","text":"Ece “iyi yaptığım için her iş bana geliyor” diyor. Deniz mentorluk saatlerinin fark edilmediğini düşünüyor. Can32 saatlik net çalışma düzenine sahip; bunu40’a çıkarmayı varsayamazsın. Mert’in destek görevleri başka ekiplerin taahhütlerini etkiliyor.","headers":[],"rows":[]}],"tasks":["Kişi bazında toplam yükü, boşluğu/açığı ve ekip toplamını hesapla.","Dört saatlik rapor için iki devir seçeneğini karşılaştır; uygulayacağın dağılımı yaz.","Ece ile bire bir görüşmenin açılışını ve ekip toplantısındaki adalet açıklamanı ayrı hazırla.","Devir sonrasında iş kalitesini ve iş yükünü izlemek için iki haftalık takip kur.","Toplam doluluğun neden kişi bazındaki sorunu gizleyebildiğini açıklayan kısa yönetici notu yaz."],"numbers":[{"id":"toplam","label":"Toplam haftalık iş yükü","value":148,"unit":"saat","tolerance":0.1,"why":"36+44+28+40=148. Net kapasite40+40+32+40=152."},{"id":"acik","label":"Ece’nin haftalık kapasite aşımı","value":4,"unit":"saat","tolerance":0.1,"why":"44−40=4 saat. Deniz4, Can4 saat boş; Mert0."},{"id":"doluluk","label":"Ekip toplam doluluk oranı","value":97.36842105263158,"unit":"%","tolerance":0.06,"why":"148/152×100≈%97,37; kişi bazındaki%110 yükü gizler."}],"rubric":[{"name":"Görünmeyen işi dahil etme","evidence":"Mentorluk ve desteği ana işten ayrı ekler; Can’ın net kapasitesini değiştirmez."},{"name":"Yetkinlikle uyumlu dağılım","evidence":"Raporu uygun becerili Deniz/Can’a verir; yükü kaynak kişiden düşer, alan kişiye ekler."},{"name":"Adalet ve iletişim","evidence":"Eşit saat dağıtımı ile adil yükü ayırır; kişileri suçlamadan ölçütleri açıklar."},{"name":"Delegasyon ve takip","evidence":"Teslim, karar sınırı, destek ve kontrol zamanını belirtir; Ece’ye görünmez kontrol yükü bırakmaz."},{"name":"Sürdürülebilirlik","evidence":"Neredeyse tam dolu ekipte yeni işler için öncelik/kapasite kararı gerektiğini söyler."}],"update":{"title":"Acil altı saat","text":"Raporu Deniz’e devrettin. Yeni, altı saatlik bir destek işi geldi; bunu yalnız Can veya Mert yapabiliyor. Son tarih bu hafta. Mevcut bütün işler de bu hafta bitmeli deniyor. Yalnız yeniden dağıtım yeterli mi?","reference":"Devir sonrası toplam yük yine148/152. Yeni iş toplam154 saat yapar →2 saat net kapasite açığı. Can4 saat boş; Mert0. Yalnız yeniden dağıtım toplam açığı çözmez. Öncelik/son tarih, yetkili ek kapasite veya onaylı kapsam değişimi gerekir; Can’ın çalışma düzeni varsayımla artırılmaz."},"solution":["Deniz36/40, Ece44/40, Can28/32, Mert40/40 saat. Ece’nin fazla yükü toplam%97,37 doluluk içinde kaybolur.","Rapor Deniz’e giderse Deniz40,Ece40,Can28,Mert40. Can’a giderse Deniz36,Ece40,Can32,Mert40. İkisi de başlangıçta uygulanabilir; takip ve bağımlılıkları değerlendir.","Ece’ye “daha hızlı çalış” demek yerine yükün nasıl biriktiğini ve görünmez kontrol işini sor. Ekipte dağılım ölçütünü açıklarken özel kişisel bilgi paylaşma."],"pitfalls":["Ortalama kapasite yeterli diye Ece’nin sorunu olmadığını söylemek.","Mentorluk saatlerini boşluk saymak.","Raporu devredip Ece’den dört saati düşmemek veya Can’ı40 saat varsaymak."],"questions":["Devir ilk hafta beklenenden uzun sürerse neyi değiştirirsin?","Bir çalışanın uzmanlaşması ekip için bağımlılık yaratıyorsa nasıl gelişim planlarsın?"],"version":"1.0.0","candidateFile":"/cases/packs/ekip-yuku-aday.md"},{"id":"hizmet-kesintisi","title":"Kesinti anında karar masası","level":3,"kind":"Önceliklendirme","minutes":60,"roles":["lead","operations","custom","analyst"],"skills":["Olay koordinasyonu","Müşteri iletişimi","Kapasite"],"brief":"09.00’da sipariş platformunda ödeme durumu sorunu bildirildi. Teknik, müşteri hizmetleri ve satış ekipleri farklı bilgiler veriyor. Sen ilk iki saatin koordinasyonunu üstlendin; teknik çözüm veya finansal iade yetkin yok.","mandate":"İlk15 dakika, ilk saat ve ikinci saat planını kur. Yinelenen işlem riskini, bilgi doğrulamayı, destek kapasitesini ve müşteri güncellemelerini birlikte ele al. Gerçek ödeme veya iade işlemi yapmıyorsun.","docs":[{"title":"09.00 sipariş anlık görüntüsü","text":"Üç durum birbirini dışlar. Risk işareti, bekleyen grubun içindeki bir alt kümedir; ayrı sipariş olarak eklenmez.","headers":["Durum","Sipariş adedi"],"rows":[["İşlenmiş",1500],["Bekleyen",350],["Başarısız",150],["Bekleyen içinde yinelenme riski işareti",60]],"file":"/cases/packs/hizmet-kesintisi-1.csv"},{"title":"Destek ekibi kapasitesi","text":"Süreler ortalama varsayımdır, iş karmaşıklığı değişebilir. Normal geliş120 talep/saat; kesinti döneminde240 talep/saat. Mevcut kuyruk200 talep. Verilen hız tüm aktif temsilciler için4 talep/saat.","headers":["Kaynak","Kişi"],"rows":[["Şu an eğitimli aktif temsilci",40],["Toplam çalışan; tamamı eğitimli değil",70],["Bir saat içinde gelebilen eğitimli ek destek",10]],"file":"/cases/packs/hizmet-kesintisi-2.csv"},{"title":"İlk mesajlar","text":"Teknik: yeniden deneme otomasyonunu durdurma önerisi incelemede; tahmini çözüm süresi doğrulanmadı. Satış: bütün müşterilere30 dakikada çözülecek diyelim. Finans: yinelenme ve tahsilat mutabakatı yapılmadan otomatik iade başlatmayın. Destek: aynı müşteriden tekrar gelen talepler olabilir; tekil talep/sipariş eşleşmesi kurulmalı. Olay günlüğü ve30 dakikalık güncelleme ritmi oluşturabilirsin.","headers":[],"rows":[]}],"tasks":["Sipariş durumlarını ve60 risk işaretini doğru özetle. Doğrulanmış bilgi ile varsayımı ayır.","Normal ve kesinti döneminde destek kuyruğunun yönünü hesapla;10 ek kişi etkisini göster.","Sorumlu, karar yetkisi, ilk eylem ve güncelleme saatini içeren olay koordinasyon tablosu yaz.","Müşteri ve yönetim için iki ayrı kısa iletişim taslağı hazırla.","Teknik çözüm sonrası yeniden deneme, mutabakat ve olay kapatma koşullarını belirt."],"numbers":[{"id":"normal","label":"Normal geliş sürerken200 talebin teorik temizlenme süresi","value":5,"unit":"saat","tolerance":0.02,"why":"40×4=160 talep/saat kapasite; net erime160−120=40;200/40=5 saat. Sabit hız/geliş varsayımıyla."},{"id":"buyume","label":"Kesintide mevcut ekiple kuyruk artışı","value":80,"unit":"talep/saat","tolerance":0.1,"why":"240−160=80 yeni kuyruk/saat."},{"id":"destek","label":"10 eğitimli ek kişi geldikten sonra kalan açık","value":40,"unit":"talep/saat","tolerance":0.1,"why":"50×4=200 kapasite;240−200=40 artış/saat. Kuyruk hâlâ erimez."}],"rubric":[{"name":"Durum bütünlüğü","evidence":"1.500+350+150=2.000 sipariş olarak özetler;60 alt kümeyi toplamın üstüne eklemez."},{"name":"Risk ve yetki","evidence":"Yeniden deneme ve iade kararını ilgili teknik/finans sahiplerine taşır; onaysız toplu işlem önermez."},{"name":"Kuyruk hesabı","evidence":"Geliş hızını kapasiteden ayırır;70 kişinin tamamını eğitimli saymaz."},{"name":"Koordinasyon","evidence":"Tek bilgi kaynağı, sorumlular, karar kaydı ve zamanlı güncellemeler kurar."},{"name":"İletişim","evidence":"Doğrulanmamış30 dakika sözü vermez; belirsizliği ve bir sonraki güncellemeyi açıklar."},{"name":"Kapanış ve öğrenme","evidence":"Teknik düzeldi bilgisini tek başına kapanış saymaz; mutabakat, müşteri takibi ve sonradan inceleme tanımlar."}],"update":{"title":"Teknik düzeldi, kuyruk kaldı","text":"10.00’da teknik sorun giderildi; talep geliş hızı tekrar120/saat oldu. İlk saat boyunca yalnız40 temsilci çalıştı, kuyruk200’den280’e çıktı.10.00’da10 ek eğitimli kişi geldi. Yeni sabit varsayımlarla kuyruk kaç saatte erir? Olayı hemen kapatır mısın?","reference":"50×4=200 kapasite, net erime200−120=80/saat;280/80=3,5 saat. Teknik iyileşme, ödeme mutabakatının ve müşteri kuyruğunun bitmesi değildir; ayrı sahiplerle izlenir."},"solution":["Toplam2.000 sipariş; riskli60, bekleyen350’nin içindedir. Başarısız150 siparişte tahsilat olup olmadığı ayrıca doğrulanmalıdır.","Mevcut ekip160 kapasiteyle kesintide80/saat kuyruk büyütür.10 ek kişi kapasiteyi200’e çıkarır;240 gelişte hâlâ40/saat artış var.","Doğrulanmış mesaj, müşteri kendi durumunu takip etme yolu, tekrar işlem yapma konusunda yetkili teknik yönlendirme ve30 dakikalık güncelleme gerekir. Kesin çözüm saati veya toplu iade sözü verilmez."],"pitfalls":["60 işareti ayrı sayıp toplam2.060 sipariş demek.","Kuyruk için200/160 hesabıyla yeni gelişleri yok saymak.","Teknik sorun düzeldiğinde finansal mutabakat ve müşteri takibini kapatmak."],"questions":["Ek destek hızının4 talep/saat olmadığı ortaya çıkarsa planı nasıl güncellersin?","Tek bir müşteriden gelen tekrar talepleri raporda nasıl ayırırsın?"],"version":"1.0.0","candidateFile":"/cases/packs/hizmet-kesintisi-aday.md"},{"id":"sube-lokasyonu","title":"Yeni şube: hangi lokasyon, neden?","level":2,"kind":"Stratejik karar","minutes":50,"roles":["lead","analyst","operations","custom"],"skills":["Lokasyon seçimi","Satış aktarımı","Duyarlılık"],"brief":"Pera Yaşam, aynı şehirde ikinci şubesini açmak istiyor. Üç lokasyonun ziyaretçi tahmini, kira ve açılış giderleri farklı. Satış müdürü B’yi, operasyon C’yi öneriyor. Yönetim kuruluna bir lokasyon seçimi ya da gerekçeli erteleme önerisi sunacaksın.","mandate":"Aylık şube faaliyet sonucunu ve mevcut şubeden kayacak satışın şirket toplamına etkisini ayır. Yüksek ziyaretçi veya en düşük kira tek başına karar olmasın. Bir öneri seç; hangi koşulda fikrini değiştireceğini açıkla.","docs":[{"title":"Aday lokasyonlar","text":"Aylık satış = ziyaretçi × dönüşüm × sepet. Brüt marj ürün değişken maliyeti sonrasıdır. Faaliyet sonucu = satış × marj − aylık sabit gider. Açılış yatırımı tek seferlik nakit çıkışıdır; aylık gider değildir. Vergi, finansman ve amortisman dahil değildir.","headers":["Lokasyon","Ziyaretçi/ay","Dönüşüm %","Sepet TL","Brüt marj %","Sabit gider TL/ay","Açılış yatırımı TL"],"rows":[["A / Merkez AVM",24000,8,800,35,400000,4800000],["B / Ana cadde",18000,10,900,38,330000,3200000],["C / Gelişen mahalle",14000,12,850,40,300000,2600000]],"file":"/cases/packs/sube-lokasyonu-1.csv"},{"title":"Mevcut şube etkisi","text":"Yeni şube satışının aşağıdaki kısmının mevcut şubeden kayacağı tahmin ediliyor. Kaybolan satışın eski şubedeki katkı oranı ayrıca verilmiştir. Eski şubenin sabit gideri azalmıyor. Şirket ek faaliyet katkısı = yeni şube faaliyet sonucu − eski şubede kaybolan katkı. Bu tahminler pilotla doğrulanmadı.","headers":["Lokasyon","Mevcut şubeden kayacak yeni satış payı %","Kaybolan satışın eski katkı oranı %"],"rows":[["A / Merkez AVM",0,35],["B / Ana cadde",20,38],["C / Gelişen mahalle",5,40]],"file":"/cases/packs/sube-lokasyonu-2.csv"},{"title":"Nakit ve saha kısıtları","text":"Bu proje için ayrılmış nakit 8.000.000 TL; açılış yatırımı sonrasında en az 2.000.000 TL rezerv korunmalı. Ek işletme sermayesi gereği henüz ölçülmedi. A için beş yıllık kira taahhüdü, B için yaya erişimi ve yükleme saatleri, C için belediye erişim düzenlemesinin tamamlanması araştırılmalı. Başvuru/izin süresi kesin değil. Ziyaretçiler aynı sayım yöntemiyle tahmin edilmiştir; bunlar gerçekleşmiş satış değildir.","headers":[],"rows":[]}],"tasks":["Üç seçeneğin aylık satışını ve faaliyet sonucunu hesapla. Mevcut şubeye etkisini ayrıca göster.","Açılış yatırımı sonrası rezerv kontrolü yap; bilinmeyen işletme sermayesini nasıl ele alacağını belirt.","Finansal katkı, müşteri erişimi, sözleşme esnekliği ve uygulama riskini içeren bir karar tablosu kur. Ağırlık kullanırsan gerekçesini yaz.","Hangi lokasyonu önerdiğini veya neden ertelediğini açıkla. Diğer iki seçeneğin neden geride kaldığını somutlaştır.","Beş slaytlık yönetim kurulu sunumu iskeleti ve karar öncesi saha doğrulama planı hazırla."],"numbers":[{"id":"b_sube","label":"B lokasyonunun aylık şube faaliyet sonucu","value":285600,"unit":"TL/ay","tolerance":0.1,"why":"18.000×0,10×900=1.620.000 satış;×0,38−330.000=285.600."},{"id":"b_grup","label":"B lokasyonunun şirkete ek faaliyet katkısı","value":162480,"unit":"TL/ay","tolerance":0.1,"why":"285.600−(1.620.000×0,20×0,38)=162.480."},{"id":"c_grup","label":"C lokasyonunun şirkete ek faaliyet katkısı","value":242640,"unit":"TL/ay","tolerance":0.1,"why":"14.000×0,12×850=1.428.000; şube sonucu 271.200; eski katkı kaybı 28.560; ek katkı 242.640."},{"id":"a_nakit","label":"A yatırımı sonrasında kalan proje nakdi","value":3200000,"unit":"TL","tolerance":0.1,"why":"8.000.000−4.800.000=3.200.000.2 milyon rezerv koşulunu ilk yatırım aşamasında sağlar; işletme sermayesi henüz dahil değildir."}],"rubric":[{"name":"Şube ve şirket ayrımı","evidence":"Yeni şube kârını eski şubenin katkı kaybıyla birlikte inceler; aktarılan satışın tamamını kâr kaybı saymaz."},{"name":"Sermaye ve rezerv","evidence":"Tek seferlik yatırımı aylık sonuca karıştırmaz; işletme sermayesinin eksik olduğunu açıklar."},{"name":"Stratejik ölçütler","evidence":"Müşteri, erişim, kira esnekliği ve açılış riskini gerekçeli ölçütlerle karşılaştırır."},{"name":"Koşullu öneri","evidence":"Bir seçenek önerir; alternatiflerin üstün yanlarını ve fikrini değiştirecek koşulu da açıklar."},{"name":"Doğrulama","evidence":"Ziyaretçi/dönüşüm/aktarım tahminlerini ve izin durumunu sahada sınayacak plan kurar."}],"update":{"title":"C’de dönüşüm beklentisi düştü","text":"Saha denemesi C’nin dönüşümünü%12 yerine%9 olarak güncelledi. Diğer tahminler aynı; kayma payı yine yeni şube satışının%5’i. Şirket ek katkısı nasıl değişir? İlk önerini korur musun?","reference":"C satış 1.071.000; şube sonucu 128.400; eski katkı kaybı 21.420; ek katkı 106.980 TL/ay. A 137.600 ve B 162.480 TL/ayla finansal sıralama değişir. İzin, rezerv ve stratejik hedefleri yeniden ele al; C’yi sırf önce onu savundun diye koruma."},"solution":["A satış 1.536.000 ve faaliyet/ek katkı 137.600 TL. B şube 285.600 ile önde görünür; şirket ek katkısı 162.480’e iner. C şube 271.200, şirket ek katkısı 242.640 TL.","İlk tahminlerde C şirket katkısı ve daha düşük yatırım açısından güçlüdür. Bu, izin ve dönüşüm belirsizliğini ortadan kaldırmaz. B daha güçlü bağımsız şube sonucuna rağmen eski satış aktarımı nedeniyle toplamda geride kalır.","A/B/C yatırım sonrası nakit 3,2/4,8/5,4 milyon TL. Yalnız bu hesap açılışın bütün nakit ihtiyacını kapsamaz. Koşullu öneri, saha verisi ve onay kapılarıyla savunulmalıdır."],"pitfalls":["Yalnız ziyaretçi sayısına veya kiraya göre seçim yapmak.","B’deki mevcut satış aktarımını yok saymak veya kaybolan ciroyu doğrudan kâr kaybı saymak.","Açılış yatırımını hem aylık gider hem başlangıç nakdi olarak çift saymak."],"questions":["C için hangi dönüşüm oranının altında B’yi yeniden değerlendirirsin?","Daha düşük kısa vadeli katkıyı stratejik erişim için seçersen bunu nasıl doğrularsın?"],"version":"1.0.0","candidateFile":"/cases/packs/sube-lokasyonu-aday.md"},{"id":"buyume-formati","title":"Yeni pazara giriş: şube, bayilik, çevrim içi?","level":2,"kind":"Stratejik karar","minutes":45,"roles":["lead","analyst","custom"],"skills":["Büyüme modeli","Likidite","Geri döndürülebilirlik"],"brief":"Kuzey Tasarım, yeni bir şehirde büyümek istiyor. Kendi mağazası marka kontrolü, bayilik düşük başlangıç gideri, çevrim içi pilot ise öğrenme esnekliği sunuyor. Aynı sermayeyle hepsini başlatamazsın.","mandate":"İlk üç aylık nakdi ve operasyon sonucunu ayrı göster. Veriler kurgusal; marka kontrolü ve müşteri deneyimi sayısal puana otomatik indirgenmez. Başlamak kadar denemek veya ertelemek de gerekçeli seçenek olabilir.","docs":[{"title":"İlk üç ayın planı","text":"Katkı, ürün ve kanala bağlı değişken giderler sonrası; sabit işletme gideri ve tek seferlik başlangıç yatırımı öncesidir. Bayilikte tutarlar bayinin cirosu değil, şirketin net katkısıdır. Tüm işletme gelir/gideri aynı ay nakde dönüşür varsayımı kullanılıyor.","headers":["Model","Başlangıç nakdi TL","Ay 1 katkı TL","Ay 2 katkı TL","Ay 3 katkı TL","Aylık sabit gider TL"],"rows":[["Kendi şubesi",1800000,90000,140000,180000,120000],["Bayilik",600000,70000,70000,70000,20000],["Çevrim içi pilot",400000,100000,130000,160000,120000]],"file":"/cases/packs/buyume-formati-1.csv"},{"title":"Sermaye sınırı","text":"Başlangıç nakdi 2.000.000 TL ve her ay sonu en az 400.000 TL korunmalı. Başlangıç yatırımı faaliyetten önce ödenir; o anda da rezerv korunmalı. Ek finansman onayı yok. Pilotun sonunda kapatma/çıkış maliyeti verilmedi.","headers":[],"rows":[]},{"title":"Model farkları","text":"Kendi şubesinde deneyim kontrolü yüksek; kira ve ekip taahhüdü uzun. Bayilikte yerel işletmecinin hizmet standardı ve sözleşme yetkileri doğrulanmalı. Çevrim içi pilotta müşteri edinme ve iade varsayımları henüz gerçek veriyle sınanmadı. İlk üç aydan sonraki hacim ve kârlılık tahmin edilmedi.","headers":[],"rows":[]}],"tasks":["Her model için üç aylık faaliyet sonucunu ve yatırım dahil ay sonu nakitlerini hesapla.","Rezerv koşulunu ihlal eden modeli belirle; muhasebesel sonuçla nakit kısıtını ayır.","Kontrol, öğrenme hızı, geri döndürülebilirlik ve kapasiteyi içeren karşılaştırma yap.","Bir başlangıç modeli veya aşamalı yol öner; neden diğerlerinden başlamadığını açıkla.","90 gün sonunda devam/ölçekleme/durdurma kararında kullanacağın kanıtları ve sınırları yaz."],"numbers":[{"id":"sube","label":"Kendi şubesinin üç aylık faaliyet sonucu","value":50000,"unit":"TL","tolerance":0.1,"why":"(90.000−120.000)+(140.000−120.000)+(180.000−120.000)=50.000."},{"id":"ilk_nakit","label":"Kendi şubesinde ilk ay sonu nakit","value":170000,"unit":"TL","tolerance":0.1,"why":"2.000.000−1.800.000−30.000=170.000; başlangıçta kalan 200.000 de 400.000 rezervin altındadır."},{"id":"bayi","label":"Bayilikte üçüncü ay sonu nakit","value":1550000,"unit":"TL","tolerance":0.1,"why":"2.000.000−600.000+3×(70.000−20.000)=1.550.000."}],"rubric":[{"name":"Faaliyet ve yatırım","evidence":"Tek seferlik yatırımı üç aylık faaliyet sonucundan ayırır; nakit hesabında dahil eder."},{"name":"Zorunlu kısıt","evidence":"Şubenin rezerv ihlalini olumlu üçüncü ay sonucu ile gizlemez."},{"name":"Model karşılaştırması","evidence":"Kontrol, yerel ortak, müşteri öğrenmesi ve çıkış esnekliğini açıklar."},{"name":"Aşamalı öneri","evidence":"Sermaye/insan kaynağıyla tutarlı bir ilk adım ve sonraki kapı önerir."},{"name":"Başarı kanıtı","evidence":"İlk üç ayı uzun vadeli başarı garantisi saymaz; devam/durdurma koşullarını tanımlar."}],"update":{"title":"Bayilikte kontrol şartı","text":"Bayi, şirketin kalite denetimine yalnız yılda bir izin vereceğini ve müşteri şikâyet verisini paylaşmayacağını söylüyor. Finansal tahminler değişmiyor. Önerini hangi şartlarla sürdürür veya değiştirirsin?","reference":"Bu bilgi gelir hesabını değiştirmese de marka/hizmet riskini ve izlenebilirliği değiştirir. Denetim, veri paylaşımı ve düzeltme yükümlülükleri için yetkili sözleşme müzakeresi gerekir. Bu koşullar sağlanmıyorsa çevrim içi pilot veya erteleme savunulabilir; sırf nakit yüksek diye onaysız sözleşme önerilmez."},"solution":["Kendi şubesinde aylık faaliyet−30.000/+20.000/+60.000 TL; üçüncü ay nakit 250.000 TL. Başlangıçtan itibaren rezerv ihlal edilir.","Bayilik aylık 50.000 TL, üç aylık 150.000 TL faaliyet sonucu ve ay 3 nakit 1.550.000 TL. Çevrim içi pilot−20.000/+10.000/+40.000, toplam 30.000 TL; ay 3 nakit 1.630.000 TL.","Bayilik güçlü kısa vadeli sonuç, pilot yüksek geri dönme/öğrenme esnekliği sunabilir. Ortak ve veri koşulları doğrulanmadan tek evrensel doğru seçenek yoktur."],"pitfalls":["Yatırımı dışarıda bırakıp tüm modellerin nakit rezervini koruduğunu söylemek.","Bayinin cirosu ile şirketin bayilik katkısını karıştırmak.","Üç aylık tahminden yıllık kesin kazanç çıkarmak."],"questions":["Pilotta öğrendiğin hangi veri mağaza kararını değiştirebilir?","Rezerv kuralı kaldırılırsa kendi şubesini otomatik seçer misin?"],"version":"1.0.0","candidateFile":"/cases/packs/buyume-formati-aday.md"},{"id":"nakit-toparlanma","title":"Şirket zor durumda: ilk dört haftayı çıkar","level":3,"kind":"Stratejik karar","minutes":60,"roles":["lead","analyst","operations","custom"],"skills":["Nakit planlama","Aksiyon sırası","Kriz koordinasyonu"],"brief":"Bir hizmet şirketinin bilançosunda alacak ve stok var; buna rağmen iki hafta içinde ödeme sıkışıklığı bekleniyor. Yönetim “önce satışları artıralım” diyor. İlk dört haftalık nakit korunma ve toparlanma planını hazırlayacaksın.","mandate":"Borçlanma veya ödeme erteleme onayı verilmiş gibi davranma; aşağıdaki seçeneklerin karşı taraf/finans onayına bağlı olduğunu belirt. Bu bir sentetik yönetim vakasıdır. Çalışan, müşteri ve operasyon yükümlülükleri için yetkili ekiplerle birlikte hareket et.","docs":[{"title":"Baz haftalık nakit planı","text":"Başlangıç nakdi 300.000 TL. Akımlar hafta sonunda netlenir; hafta içi gün bazlı sıralama ayrıca doğrulanmalı. Alacak/stok toplamları bu tablonun üstüne nakit olarak eklenmez.","headers":["Hafta","Tahsilat TL","Ödeme TL"],"rows":[["1",200000,450000],["2",250000,550000],["3",500000,400000],["4",450000,350000]],"file":"/cases/packs/nakit-toparlanma-1.csv"},{"title":"Görüşülebilen aksiyonlar","text":"1) Üçüncü haftada beklenen tahsilatın 200.000 TL’si ikinci haftaya alınabilir; toplam tahsilat artmaz.2) İkinci haftanın 300.000 TL tedarikçi ödemesi dördüncü haftaya kayabilir; toplam ödeme azalmaz.3) Finans onaylarsa ilk haftanın başında en fazla 200.000 TL geçici kaynak sağlanabilir; geri ödeme 8. haftada, bu ufkun dışında. Faiz/gider bu basitleştirilmiş tabloda yok, son karar için ayrıca gerekir.","headers":[],"rows":[]},{"title":"Yönetim bilgisi","text":"Her hafta sonunda en az 100.000 TL tampon hedefleniyor. Bilançoda 2.000.000 TL alacak,3.000.000 TL stok bulunması bunların hemen nakit olduğu anlamına gelmiyor. Yeni satışın tahsilat süresi henüz bilinmiyor. Tedarikçi ertelemesinin kritik hizmeti kesip kesmeyeceği doğrulanmalı.","headers":[],"rows":[]}],"tasks":["Baz senaryoda her hafta sonu nakdi, en düşük noktayı ve 100.000 TL tampon için gereken başlangıç desteğini hesapla.","Erken tahsilat ile ödeme ertelemesini birlikte uygula; çift saymadan yeni planı çıkar.","Geçici kaynak üst sınırıyla tampon hedefinin hangi aksiyon birleşiminde sağlanabileceğini göster.","İlk 48 saat için sorumlu, onay, teyit zamanı ve başarısız olursa alternatif içeren aksiyon tablosu yaz.","Satış, stok ve alacak için 30 günlük ek inceleme öner; nakit korunmasıyla kalıcı kârlılığı ayır."],"numbers":[{"id":"dip","label":"Baz senaryodaki en düşük hafta sonu nakit","value":-250000,"unit":"TL","tolerance":0.1,"why":"Hafta sonları 50.000,−250.000,−150.000,−50.000 TL; dip ikinci haftada."},{"id":"baz_destek","label":"Baz senaryoda 100.000 tampon için gereken başlangıç desteği","value":350000,"unit":"TL","tolerance":0.1,"why":"100.000−(−250.000)=350.000;200.000 üst sınır tek başına yetmez."},{"id":"birlesik","label":"İki zamanlama aksiyonu sonrası dördüncü hafta nakdi, desteksiz","value":-50000,"unit":"TL","tolerance":0.1,"why":"Erken tahsilat/erteleme sonrası 50.000,250.000,150.000,−50.000. Ufuk toplamı değişmediği için son nakit değişmez."},{"id":"ek_destek","label":"İki zamanlama aksiyonuyla 100.000 tamponu koruyan asgari destek","value":150000,"unit":"TL","tolerance":0.1,"why":"Yeni dip−50.000;100.000 tampon için 150.000 başlangıç desteği. Hafta sonları 200.000,400.000,300.000,100.000 olur."}],"rubric":[{"name":"Nakit bütünlüğü","evidence":"Haftalık bakiyeyi önceki haftadan devreder; alacağı/stoku nakit diye eklemez."},{"name":"Zamanlama ve tutar","evidence":"Erken tahsilatı ve ertelenen ödemeyi iki haftada karşılıklı işler; kalıcı kazanç saymaz."},{"name":"Uygulanabilir birleşim","evidence":"200.000 finansman sınırını ve 100.000 tamponu birlikte denetler."},{"name":"Öncelik ve yetki","evidence":"48 saatlik teyit/onay akışını ve kritik operasyon etkisini tanımlar."},{"name":"Kalıcı toparlanma","evidence":"Dört haftayı kurtarmanın zarar modelini çözmediğini açıklar."},{"name":"Belirsizlik planı","evidence":"Tahsilat ve tedarikçi onayı gerçekleşmezse tetiklenecek alternatifleri belirtir."}],"update":{"title":"Tahsilat gecikmesi","text":"Üçüncü haftada, erken tahsil edilen 200.000 TL dışındaki tahsilatın 200.000 TL’si beşinci haftaya kaldı. Diğer aksiyonlar aynı. Tamponu korumak için toplam geçici kaynak ihtiyacı ne olur;200.000 TL tavan yeter mi?","reference":"Zamanlama aksiyonları sonrası desteksiz bakiyeler 50.000,250.000,−50.000,−250.000 TL olur.100.000 tampon için 350.000 toplam destek gerekir;200.000 tavanın 150.000 üzerindedir. Ek doğrulanmış tahsilat, uygun gider/taahhüt değişimi veya yetkili farklı kaynak gerekir; ödemeleri sessizce durdurmak plan değildir."},"solution":["Baznakit 50.000/−250.000/−150.000/−50.000. Dip−250.000; tamponlu gereksinim 350.000 TL.","İki zamanlama aksiyonu 50.000/250.000/150.000/−50.000 yapar. Toplam nakit açığı bitmez;150.000 onaylı ek kaynakla tampon korunur.","Önce günlük nakit görünürlüğü, tahsilat/erteleme teyidi, kaynak onayı ve kritik hizmet etkisi. Sonraki 30 günde marj, stok dönüşü, alacak vadesi ve taahhütler incelenir. Yeni satışın nakdi ne zaman getirdiği bilinmeden çözüm sayılmaz."],"pitfalls":["300.000 TL ertelemeyi kalıcı maliyet tasarrufu saymak.","Erken tahsilatı ikinci haftaya ekleyip üçüncü haftadan düşmemek.","Stok 3 milyon diye nakit açığı olmadığını söylemek."],"questions":["Hafta içindeki ödeme sırası hafta sonu planını neden yetersiz bırakabilir?","Zarardaki şirkette satış büyümesi hangi koşulda nakit sorununu artırır?"],"version":"1.0.0","candidateFile":"/cases/packs/nakit-toparlanma-aday.md"},{"id":"zarar-portfoyu","title":"Zarar eden işi kapatmak her zaman çözüm mü?","level":3,"kind":"Stratejik karar","minutes":60,"roles":["lead","analyst","custom"],"skills":["Katkı analizi","Kaçınılabilir maliyet","Portföy kararı"],"brief":"Bir şirketin üç ürün hattından ikisi dağıtılmış gider sonrası zararda görünüyor. Yönetim ikisini de kapatmayı düşünüyor. Hangi işin gerçekten katkı sağladığını ve hangi maliyetin kapanınca ortadan kalkacağını inceleyeceksin.","mandate":"Dağıtılmış genel gider ile kaçınılabilir doğrudan gideri ayır. Kapatma, fiyat/ürün değişimi, küçültme veya sürdürmeyi karşılaştır. Sadece en düşük raporlanmış kârı olan işi kapatma.","docs":[{"title":"Aylık ürün hattı tablosu","text":"Doğrudan sabit gider, hat kapanırsa 30 gün sonra tamamen ortadan kalkabilecek tutardır. Aylık merkez gideri toplam 300.000 TL; hatlara eşit 100.000 dağıtılmıştır ve kapanışla otomatik azalmaz.","headers":["Hat","Satış TL","Değişken gider TL","Kaçınılabilir doğrudan sabit gider TL","Dağıtılmış merkez gideri TL"],"rows":[["A",1200000,840000,180000,100000],["B",800000,560000,200000,100000],["C",500000,400000,140000,100000]],"file":"/cases/packs/zarar-portfoyu-1.csv"},{"title":"Kapatma etkileri","text":"C’nin kapatılması A’da aylık 80.000 TL satış kaybettirebilir; A’nın bu satıştaki katkı oranı%30, A sabit gideri değişmez. C’nin tek seferlik kapanış gideri 50.000 TL. B kapanışının başka satışa etkisi veya kapanış gideri bu karşılaştırmada sıfır varsayılmıştır; sözleşmelerle ayrıca doğrulanmalı.","headers":[],"rows":[]},{"title":"C için alternatif","text":"C fiyatı%10 artırırsa hacmin%20 düşeceği varsayılıyor. Değişken gider hacimle orantılı, doğrudan sabit gider değişmiyor. Bu seçenek A satışını etkilemiyor varsayımı kullanılıyor. Talep tepkisi henüz pilotla doğrulanmadı. Merkez gideri için somut azaltım onayı yok.","headers":[],"rows":[]}],"tasks":["Hat bazında katkıyı, doğrudan sonucu ve dağıtım sonrası sonucu hesapla; şirket toplamına bağla.","B kapanırsa şirket sonucunun nasıl değiştiğini göster.","C kapanışını ilk geçiş dönemi giderinden ayrı, sürekli durum etkisiyle değerlendir; A satışını dahil et.","C fiyat değişimi alternatifini hesapla; kapanışla kıyasla ve tahmin riskini açıkla.","Bir portföy önerisi ve 30/60 günlük doğrulama planı hazırla; hâlâ kalan zararı görünür tut."],"numbers":[{"id":"b_katki","label":"B hattının aylık katkısı, doğrudan sabit gider öncesi","value":240000,"unit":"TL","tolerance":0.1,"why":"800.000−560.000=240.000; doğrudan sabit sonrası 40.000; merkez dağıtımı sonrası−60.000."},{"id":"toplam","label":"Mevcut şirket aylık faaliyet sonucu","value":-120000,"unit":"TL","tolerance":0.1,"why":"A 180.000+B 40.000+C(−40.000)−300.000=−120.000."},{"id":"b_kapat","label":"Yalnız B kapandıktan sonraki sürekli şirket sonucu","value":-160000,"unit":"TL","tolerance":0.1,"why":"B’nin 40.000 net doğrudan katkısı kaybolur; merkez gideri kalır.−120.000−40.000=−160.000."},{"id":"c_kapat","label":"Yalnız C kapandıktan sonraki sürekli şirket sonucu","value":-104000,"unit":"TL","tolerance":0.1,"why":"C kapanışı 140.000 sabit tasarruf−100.000 kayıp katkı−24.000 A katkı kaybı=16.000 iyileşme;−104.000 sonuç. Tek seferlik 50.000 ayrıca."}],"rubric":[{"name":"Maliyet ayrımı","evidence":"Katkı, kaçınılabilir sabit ve dağıtılmış merkez giderini ayrı hesaplar."},{"name":"Toplam şirket etkisi","evidence":"Bir hattın zararlı görünmesini şirket toplamını iyileştiren kapanışla karıştırmaz."},{"name":"Bağlantılı satış","evidence":"C’nin A satışına etkisini katkı oranıyla işler; kaybolan cironun tümünü kâr kaybı saymaz."},{"name":"Geçiş ve sürekli durum","evidence":"30 günlük gider kalkışını,50.000 tek seferlik gideri ve sürekli sonucu ayrı gösterir."},{"name":"Alternatif ve kanıt","evidence":"Fiyat/hacim varsayımını sınamayı önerir; iyileşmenin zararı tamamen çözmediğini saklamaz."},{"name":"Uygulama","evidence":"Ürün, müşteri ve ekip geçişini sahip/tarih/karar kapısıyla planlar."}],"update":{"title":"Merkez gideri önerisi","text":"Yönetim üç ay sonra 60.000 TL aylık merkez gideri azaltabilecek bir plan önerdi; henüz onaylı değil. B’yi kapatmaya gerekçe olarak bu tasarrufu yalnız B’ye yazabilir misin? İlk ay nakdi ile dördüncü ay sonucunu nasıl ayırırsın?","reference":"Bağımsız merkez tasarrufu B kapanışının doğrudan faydası gibi yazılmaz; hangi karara bağlı olduğu doğrulanır. B’yi koruyup merkez giderini azaltma da karşılaştırılmalı. Üç ay sonra başlayacak fayda ilk ayın nakdine eklenemez."},"solution":["Dağıtım sonrası A 80.000/B−60.000/C−140.000 TL; toplam−120.000. B merkez giderini taşımaya 40.000 TL katkı verir. Kapanışı sonucu−160.000 yapar.","C kapanışı sürekli durumda 16.000 TL iyileştirir, şirket hâlâ−104.000 TL’dedir; geçiş maliyeti ve giderin kalkacağı tarih ayrı önemlidir.","C fiyat seçeneği satış 440.000, değişken 320.000, doğrudan sabit 140.000 →−20.000 doğrudan sonuç; bazdan 20.000 iyileşme ile şirket−100.000. Tahminler tutarsa kapanıştan biraz iyi; müşteri tepkisi doğrulanmalıdır."],"pitfalls":["Dağıtılmış merkez giderinin kapanışla yok olacağını varsaymak.","B’nin−60.000 raporlanmış zararını kapanış tasarrufu saymak.","C kapanışının A etkisini veya geçiş zamanını yok saymak."],"questions":["Kaçınılabilir diye etiketlenen sabit gideri nasıl doğrularsın?","Fiyat artışı sonrası hacim yalnız%10 düşerse C için görüşün nasıl değişir?"],"version":"1.0.0","candidateFile":"/cases/packs/zarar-portfoyu-aday.md"},{"id":"doksan-gun-toparlanma","title":"Şirketi 90 günde toparla: önce hangi aksiyonlar?","level":3,"kind":"Stratejik karar","minutes":65,"roles":["lead","analyst","operations","custom"],"skills":["Stratejik öncelik","Kaynak kısıtı","30/60/90 planı"],"brief":"Dora Hizmet’in satışları yüksek ama şirket her ay zarar ediyor. Yönetim fiyat artışı, tedarikçi pazarlığı, kalite, stok ve büyük bir sistem yatırımı arasında bölünmüş. İlk 30 günün kaynakları sınırlı;90 günlük bir yol çizmen bekleniyor.","mandate":"Aşağıdaki faydalar tahmindir; tam uygulama sonrası aylık etkiyi gösterir, ilk ayın otomatik gerçekleşmesi değildir. Kalıcı kârlılık, tek seferlik nakit ve gelecekteki öğrenme faydasını ayır. Her aksiyonu aynı anda başlatma.","docs":[{"title":"Aylık baz","text":"Satış 10.000.000 TL, değişken gider 7.000.000 TL, sabit gider 3.400.000 TL. Ürün/hizmet karması sabit varsayılıyor. İlk 30 gün için dönüşüm bütçesi 1.200.000 TL ve en fazla 6 kişi-hafta uygulama kapasitesi var; günlük operasyon kapasitesi bu havuza dahil değil.","headers":[],"rows":[]},{"title":"Aksiyon seçenekleri","text":"Aylık faydalar birbirini dışlamayan tahminlerdir; aynı maliyetin iki aksiyonla azaltılması varsa bağımsızlık doğrulanmalı. Stok aksiyonu yalnız nakit serbestleştirir.","headers":["ID","Aksiyon","Başlangıç nakdi TL","Tam uygulamada aylık sonuç etkisi TL","Kişi-hafta"],"rows":[["F","Fiyat%2; hacim sabit varsayımı",100000,200000,2],["T","Tedarik koşullarını iyileştir",0,150000,2],["S","Fazla stoktan nakit çıkar",50000,"500000 tek seferlik nakit girişi",1],["K","Yeniden işlemi azalt",200000,100000,3],["E","Yeni ERP",900000,"İlk 3 ay fayda yok; ay 6 sonrası belirsiz",8],["P","Yeni müşteri segmenti pilotu",250000,"Henüz ölçülmedi",3]],"file":"/cases/packs/doksan-gun-toparlanma-2.csv"},{"title":"Karar ortamı","text":"Tedarik kazancı kalite standardı düşürülmeden aranmalı. Stok satışı defter değerinden ve mevcut alıcıyla varsayılmıştır; gelir/kâr etkisi bu tabloda sıfırdır. ERP’nin 8 kişi-haftalık işi ilk 30 günde bölünmeden tamamlanacak kapsam olarak teklif edildi; bu kapsam kapasiteyi aşıyor. Fiyat/hacim tepkisi ve uygulamaya geçiş tarihleri belirsiz.","headers":[],"rows":[]}],"tasks":["Baz katkı ve faaliyet zararını hesapla; şirketin temel sorununu bir paragrafta çerçevele.","İlk 30 gün için seçtiğin aksiyonların bütçe ve kişi-hafta toplamını göster; seçmediklerini gerekçelendir.","F/T/K’nin tam uygulama aylık etkisini ve ilk ayla farkını açıkla. S aksiyonunu kâr gibi göstermeden nakde bağla.","30/60/90 günlük plan hazırla: sorumlu, başlama önkoşulu, çıktı, kontrol göstergesi ve durdurma koşulu.","Yönetimden istediğin üç kararı ve henüz bilinmeyen kritik varsayımları yaz."],"numbers":[{"id":"baz","label":"Baz aylık faaliyet sonucu","value":-400000,"unit":"TL/ay","tolerance":0.1,"why":"10.000.000−7.000.000−3.400.000=−400.000."},{"id":"stok","label":"S aksiyonunun başlangıç gideri sonrası tek seferlik net nakit etkisi","value":450000,"unit":"TL","tolerance":0.1,"why":"500.000 giriş−50.000 çıkış=450.000; aylık kâr artışı değildir."},{"id":"kapasite","label":"F,T,S,K aksiyonlarının toplam ilk dönem kapasite ihtiyacı","value":8,"unit":"kişi-hafta","tolerance":0,"why":"2+2+1+3=8;6 kişi-hafta sınırını aşar. F/T/K bile 7 gerektirir."},{"id":"tam","label":"F,T,K tam uygulanırsa baz varsayımlarla aylık faaliyet sonucu","value":50000,"unit":"TL/ay","tolerance":0.1,"why":"−400.000+200.000+150.000+100.000=50.000. Fayda başlangıç tarihleri ve bağımsızlığı doğrulanmalıdır."}],"rubric":[{"name":"Sorunu ayrıştırma","evidence":"Ciro, katkı, faaliyet zararı ve likiditeyi ayrı gösterir."},{"name":"Kaynak gerçekçiliği","evidence":"İlk 30 günün 6 kişi-hafta ve nakit sınırını aşmayan seçim yapar; hepsini eşzamanlı yazmaz."},{"name":"Fayda niteliği ve zaman","evidence":"Stok nakdini aylık kâr saymaz; tam uygulama faydasını ilk ay gerçekleşmesi gibi sunmaz."},{"name":"Öncelik ve vazgeçiş","evidence":"Seçilmeyen aksiyonların neden beklediğini ve hangi kanıtla öne alınacağını açıklar."},{"name":"Aksiyon planı","evidence":"Sorumlu, önkoşul, ölçüt, tarih ve kontrol kapılarını bağlar."},{"name":"Duyarlılık","evidence":"Fiyat/hacim, kalite ve fayda çakışması risklerini sınar; sonucu garanti etmez."}],"update":{"title":"Fiyat sonrası hacim kaybı","text":"Fiyat%2 artınca hacim%3 düştü. Değişken gider hacimle orantılı, sabit gider aynı kaldı. F’nin aylık katkı iyileşmesi artık ne kadar? T/K tahminleri aynı kalsa şirket kâra geçer mi?","reference":"Satış 10.000.000×1,02×0,97=9.894.000; değişken gider 7.000.000×0,97=6.790.000; katkı 3.104.000 →104.000 iyileşme. T 150.000 ve K 100.000 ile toplam 354.000 iyileşir; şirket−46.000 TL/ayda kalır. F’nin 200.000 varsayımı korunamaz."},"solution":["Baz zarar 400.000 TL/ay. Stok aksiyonu 450.000 tek seferlik net nakit getirir, zarar modelini tek başına çözmez.","Örnek ilk dönem F/T/S:5 kişi-hafta ve 150.000 başlangıç gideri; F+T tam uygulanınca 350.000/ay potansiyel iyileşme, kalan 50.000 zarar. F/K/S:6 kişi-hafta ve 350.000 gider;300.000/ay iyileşme. Bunlar tek geçerli seçim değildir.","Kritik uygulama ve kalite kapılarıyla sonraki dönemde kapsam genişletilebilir. ERP ilk 30 gün kapasitesine sığmaz, ilk 3 ay kâr çözümü değildir; stratejik değerini ayrı yol haritasında incelemek gerekir."],"pitfalls":["Altı aksiyonu birden başlatıp kapasite hesabı yapmamak.","Stok satışını her ay tekrarlanan kâr artışı saymak.","Fiyat artışının hacmi hiç etkilemeyeceğini kesin kabul etmek."],"questions":["Kâr getiren aksiyonun nakit etkisi gecikirse sıranı nasıl değiştirirsin?","Hangi iki faydanın aynı maliyet kalemini azalttığını nasıl kontrol edersin?"],"version":"1.0.0","candidateFile":"/cases/packs/doksan-gun-toparlanma-aday.md"},{"id":"kapasite-ortakligi","title":"Büyüyen talep: yatırım mı, ortaklık mı?","level":2,"kind":"Stratejik karar","minutes":50,"roles":["lead","operations","analyst","custom"],"skills":["Yap veya satın al","Geçiş modeli","Hizmet riski"],"brief":"Bir hizmet işletmesi mevcut kapasitesinin üzerinde aylık 800 sipariş fırsatı görüyor. Talebin ne kadar kalıcı olduğu bilinmiyor. Kendi kapasitesini büyütme, iş ortağı kullanma ve geçici karma model seçeneklerini karşılaştıracaksın.","mandate":"Sipariş başına 250 TL, yeni karşılama maliyeti öncesi katkıdır; satış geliri değildir. Aşağıdaki maliyetleri ayrıca düş. Uzun vadeli yatırım ile sekiz haftalık geçiş modelini aynı kalıcılıkta kabul etme.","docs":[{"title":"Karşılama seçenekleri","text":"Aylık 800 ek siparişin tamamının talep edildiği varsayılıyor. Yatırım tek seferliktir; aylık sabit giderler ek maliyetlerdir. Vergi, finansman, kurulum gecikmesi dahil değil.","headers":["Model","Başlangıç TL","Kapasite sipariş/ay","Aylık sabit TL","Sipariş başı karşılama TL"],"rows":[["Kendi kapasitesi",2400000,1000,150000,60],["İş ortağı",200000,800,30000,140],["Karma geçiş",250000,800,35000,"600 sipariş×140;200 sipariş×90"]],"file":"/cases/packs/kapasite-ortakligi-1.csv"},{"title":"Uygulama koşulları","text":"Karma modelde 200 siparişlik iç ek çalışma en fazla sekiz hafta için onaylanabilir; kalıcı çözüm değildir. İş ortağının hata/teslim performansı henüz pilotla doğrulanmadı. Kendi yatırımının başlama süresi ve siparişin devamlılığı belirsiz; ekip eğitimi gerekir.","headers":[],"rows":[]},{"title":"Yönetim beklentisi","text":"Yalnız en yüksek aylık farkı seçmek yerine hizmet standardı, bilgi güvenliği, müşteri etkisi, talebin düşmesi ve geri dönüş esnekliğini ele al. İlk aşamada sınırlı hacimli bir pilot veya erteleme önerebilirsin; bunun kaçan katkısını da açıkla.","headers":[],"rows":[]}],"tasks":["800 siparişte her seçeneğin ek aylık faaliyet sonucunu hesapla.","Başlangıç nakdi ve devamlılık koşullarını karşılaştır; karma modelin ne zaman bitmesi gerektiğini yaz.","Talep 400 siparişe düşerse kendi kapasitesi ile iş ortağını karşılaştır.","Bir ilk adım seç; iki alternatifi neden beklettiğini gerekçelendir.","Dört haftalık pilot için hizmet, kalite ve maliyet ölçütleriyle devam/durdurma kapısı kur."],"numbers":[{"id":"kendi","label":"800 siparişte kendi kapasitesinin aylık ek sonucu","value":2000,"unit":"TL/ay","tolerance":0.1,"why":"800×(250−60)−150.000=2.000."},{"id":"ortak","label":"800 siparişte iş ortağı modelinin aylık ek sonucu","value":58000,"unit":"TL/ay","tolerance":0.1,"why":"800×(250−140)−30.000=58.000."},{"id":"karma","label":"800 siparişte karma geçişin aylık ek sonucu","value":63000,"unit":"TL/ay","tolerance":0.1,"why":"600×(250−140)+200×(250−90)−35.000=63.000; yalnız geçiş süresinde uygulanabilir."}],"rubric":[{"name":"Katkı tanımı","evidence":"250 TL’yi satışla karıştırmaz; yeni birim ve sabit maliyetleri ayrıca düşer."},{"name":"Süre ve kapasite","evidence":"Karma modelin sekiz haftalık sınırını ve kendi yatırımının başlangıç süresini ele alır."},{"name":"Talep duyarlılığı","evidence":"Sabit maliyeti yüksek modelin düşük talepteki kaybını hesaplar."},{"name":"Operasyon ve müşteri riski","evidence":"İş ortağı kalite, veri ve teslim koşullarını doğrulamadan ölçeklemez."},{"name":"Aşamalı öneri","evidence":"Pilot, öğrenme, geçiş sonu ve kalıcı karar kapılarını bağlar."}],"update":{"title":"Talep yarıya düştü","text":"Bir müşteri projeyi erteledi; ek talep 400 sipariş/ay. İş ortağının sabit/birim fiyatı aynı. Kendi kapasitesi yatırımının maliyetleri de değişmiyor. İki modelin aylık sonuçları ve seçimin nasıl değişir?","reference":"Kendi:400×190−150.000=−74.000. İş ortağı:400×110−30.000=14.000 TL/ay. Bu duyarlılık kalıcı yatırımın talep riskini gösterir; yatırımın başka doğrulanmış faydaları yokken bunları uydurup zararı kapatma."},"solution":["800 siparişte kendi 2.000, ortak 58.000, karma 63.000 TL/ay. Karma yalnız sekiz haftalık geçiştir; kalıcı en iyi model diye sunulamaz.","İş ortağıyla ölçülü pilot, düşük başlangıç ve daha düşük sabit yük nedeniyle savunulabilir. Ortak kalite riski veya veri koşulları kabul edilemiyorsa farklı öneri gerekebilir.","Kendi yatırımının kapasitesi 1.000 olsa da karşılığı olmayan 200 siparişi gerçekleşmiş kazanç sayma. Talep ve hizmet kanıtını yatırım kapısına bağla."],"pitfalls":["250 TL katkıyı gelir sanıp bir kez daha ürün maliyeti düşmek.","Karma modeli sınırsız fazla çalışmayla sürekli hale getirmek.","Boş kapasiteyi kesin satış olarak yazmak."],"questions":["İş ortağının hata oranı yükselirse hangi maliyetleri karşılaştırmaya eklersin?","Talep 1.000’i aşarsa hangi yeni veri gerekir?"],"version":"1.0.0","candidateFile":"/cases/packs/kapasite-ortakligi-aday.md"},{"id":"musteri-toparlanma","title":"Müşteri artıyor, şirket neden toparlanmıyor?","level":2,"kind":"Stratejik karar","minutes":50,"roles":["lead","analyst","custom"],"skills":["Müşteri kaybı","Katkı ve indirim","Kohort"],"brief":"Bir abonelik işletmesi müşteri sayısını 1.000’den 1.100’e çıkardı ama hâlâ zarar ediyor. Satış her müşteriye indirim, hizmet ekibi ise hedefli elde tutma ve kalite iyileştirmesi öneriyor. Ekonomiyi ve öğrenme ihtiyacını birlikte ele alacaksın.","mandate":"İlk müşteri kohortunun kaybını yeni kazanımla gizleme. Katkı ve indirim maliyetini tüm ilgili müşterilerde hesapla. Elde tutma tahminleri deney sonucu değil, senaryo varsayımıdır.","docs":[{"title":"Aylık müşteri hareketi","text":"Başlangıç kohortu 1.000 müşteri. Bunların 800’ü kaldı,200’ü ayrıldı.300 yeni müşteri eklendi; dönem sonunda 1.100 aktif müşteri var. Aktif müşteri başına aylık katkı 200 TL, sabit gider 260.000 TL varsayılmıştır. Yeni/eski müşteri katkısının eşitliği henüz doğrulanmadı.","headers":[],"rows":[]},{"title":"Aksiyon seçenekleri","text":"Aşağıdaki elde tutulan müşteri sayıları mevcut 1.100’e ek, kaybı önlendiği varsayılan müşterilerdir; tahminler çakışıyorsa fayda toplanamaz.","headers":["Aksiyon","Ek tutulan müşteri","Gider kapsamı"],"rows":[["Herkese indirim",100,"Mevcut 1.100 ve ek 100 müşterinin tamamına her ay 50 TL"],["Hedefli çalışma",60,"Bir defalık 15000 TL; ek aylık gider yok varsayımı"],["Hizmet kalite desteği",80,"Her ay 30000 TL; diğer kalite faydaları henüz ölçülmedi"]],"file":"/cases/packs/musteri-toparlanma-2.csv"},{"title":"Değerlendirme ufku","text":"İlk ay etkisini ve üç aylık etkiyi ayrı gösterebilirsin. Üç aylık hesapta ek tutulan müşterilerin her ay aktif ve katkısının aynı kaldığı varsayılmalı; bu kalıcılık doğrulanmadı. İndirim dışında katkı 200 TL/müşteri/ay sabittir. Kampanya yapılmasa da 200 ayrılmanın sonraki ay aynen tekrarlanacağı kesin değildir.","headers":[],"rows":[]}],"tasks":["Başlangıç kohortunun kayıp oranını ve dönem sonu müşteri sayısını hesapla. Net büyümenin neyi gizlediğini açıkla.","Baz faaliyet sonucunu ve herkese indirim seçeneğinin ek aylık etkisini hesapla.","Hedefli çalışmayı ilk ay ve üç aylık varsayımsal ufukta değerlendir; baz zararı da göster.","Bir kontrollü deneme seç; karşılaştırma, süre, başarı/durdurma ölçütlerini tanımla.","Yönetim için “müşteri sayısı artışı” yerine birlikte takip edilecek dört gösterge öner."],"numbers":[{"id":"kayip","label":"Başlangıç kohortunun aylık müşteri kayıp oranı","value":20,"unit":"%","tolerance":0.05,"why":"200/1.000×100=%20. Yeni 300 müşteri bu kohort kayıp oranının paydasına eklenmez."},{"id":"baz","label":"Baz aylık faaliyet sonucu","value":-40000,"unit":"TL/ay","tolerance":0.1,"why":"1.100×200−260.000=−40.000."},{"id":"indirim","label":"Herkese indirim seçeneğinin baza göre ek aylık sonuç etkisi","value":-40000,"unit":"TL/ay","tolerance":0.1,"why":"Ek 100×200=20.000 katkı;1.200 müşteriye×50=60.000 indirim; net−40.000. Yeni faaliyet sonucu−80.000 TL/ay."}],"rubric":[{"name":"Kohort ve büyüme","evidence":"%20 eski müşteri kaybını%10 net büyümeyle karıştırmaz."},{"name":"Kapsamlı indirim maliyeti","evidence":"İndirim alan 1.200 müşteriyi dahil eder; yalnız ek 100’e maliyet yazmaz."},{"name":"Ufuk ve kalıcılık","evidence":"Hedefli çalışmanın tek seferlik giderini ve çok aylık kalıcılık varsayımını ayırır."},{"name":"Nedensel kanıt","evidence":"Elde tutulan müşteri tahminini kanıtlanmış etki saymaz; kontrollü ölçüm önerir."},{"name":"Toparlanma önerisi","evidence":"Müşteri sayısı, katkı, kayıp ve nakit/kaliteyi birlikte izler; kâr açığının kaldığını gösterir."}],"update":{"title":"Yeni müşteri katkısı farklı","text":"Yeni 300 müşterinin aylık katkısının 200 TL değil 100 TL olduğu anlaşıldı. Kalan eski 800 müşteride 200 TL geçerli. Baz faaliyet sonucunu ve büyüme yorumunu nasıl güncellersin?","reference":"800×200+300×100−260.000=−70.000 TL/ay. Baş sayısı artarken ortalama katkı düşebilir. Yeni kazanımla elde tutmayı aynı müşteri katkısıyla karşılaştırmak artık geçersizdir; aksiyonun hangi kohortu etkilediği ayrıştırılmalı."},"solution":["Eski kohort kaybı%20, net müşteri büyümesi%10. Biri diğerinin yerine geçmez. Baz zarar 40.000 TL/ay.","Herkese indirim, ek 100’ün katkısını 20.000 artırırken toplam 60.000 indirim yaratır; baza göre 40.000 kötüleşir.","Hedefli çalışma ilk ay 60×200−15.000=−3.000 ek etki, üç ayda 60×200×3−15.000=21.000 olumlu ek etki; üç aylık baz−120.000 zararı−99.000’e getirir, kalıcılık ve bağımsız etki varsayımıyla. Hizmet desteğinin yalnız verilen elde tutma faydası 16.000−30.000=−14.000/ay; diğer kalite faydaları ayrıca ölçülmeli."],"pitfalls":["Ayrılan 200 kişiyi dönem sonu 1.100’e bölüp kohort kayıp oranı demek.","İndirimi yalnız ek tutulan 100 müşteri için hesaplamak.","Üç aylık müşteriyi kalıcı kabul edip yaşam boyu değer uydurmak."],"questions":["Hedefli çalışmanın zaten kalacak müşterilere gittiğini nasıl fark edersin?","Kısa vadede olumsuz görünen kalite desteğinin uzun vadeli değerini nasıl sınarsın?"],"version":"1.0.0","candidateFile":"/cases/packs/musteri-toparlanma-aday.md"},{"id":"buyuk-musteri","title":"Büyük sözleşme mi, dengeli müşteri portföyü mü?","level":3,"kind":"Stratejik karar","minutes":60,"roles":["lead","analyst","custom"],"skills":["Nakit ve kârlılık","Müşteri yoğunlaşması","Büyüme kararı"],"brief":"Bir şirket yeni iş alanına girmek için iki fırsatı değerlendiriyor: büyük bir kurumsal müşteri veya daha küçük müşterilerden oluşan portföy. Büyük sözleşme daha yüksek aylık sonuç vaat ediyor, fakat ödeme vadesi uzun.","mandate":"Kârlılık, ilk üç aylık fonlama ve müşteri yoğunlaşmasını birlikte değerlendir. Bu proje için ayrılmış nakit 4.000.000 TL ve korunacak rezerv 500.000 TL; mevcut işlerin nakdi bu tutarın dışında tutuldu. Tahsilat takvimini aylık varsayımla kullan, günlük dip ayrıca araştırılmalı.","docs":[{"title":"İki yeni iş seçeneği","text":"Başlangıç gideri faaliyetten önce ödenir. Değişken ve sabit giderler aynı ay ödenir; kapasite iki seçenek için de yeterli varsayılır. Vergi/finansman yoktur.","headers":["Seçenek","Aylık satış TL","Katkı oranı %","Ek sabit gider TL/ay","Başlangıç nakdi TL"],"rows":[["Büyük sözleşme",2000000,25,180000,300000],["Küçük müşteri portföyü",1200000,35,160000,600000]],"file":"/cases/packs/buyuk-musteri-1.csv"},{"title":"Tahsilat","text":"Büyük sözleşmede ilk üç ay hiç tahsilat yok; ilk ödeme 4. ayda. Küçük müşteri portföyünde o ayki satışın%75’i aynı ay, kalan%25’i sonraki ay alınır. İlk ay önceden kalan alacak yoktur. Katkı oranı ürün/hizmet değişken gideri sonrası, ek sabit gider öncesidir.","headers":[],"rows":[]},{"title":"Ticari risk ve yetki","text":"Büyük seçenekte yeni işin tüm geliri tek müşteriye bağlıdır. Küçük portföy 40 müşteriden oluşur, en büyüğü bu portföy satışının%8’idir. Büyük sözleşmenin hacim garantisi ve erken fesih koşulları, küçük portföyün satış/servis kapasitesi henüz doğrulanmadı. Peşinat veya teminat için yetkili ticari müzakere gerekir.","headers":[],"rows":[]}],"tasks":["Her seçeneğin aylık faaliyet sonucunu hesapla; daha kârlı görüneni belirle.","Büyük sözleşmede ilk üç aylık nakit ihtiyacını ve rezervi koruyan ek fonlamayı hesapla.","Küçük portföyde başlangıç ve ilk ay sonunda kalan nakdi göster.","Yoğunlaşma, vade, fesih ve hizmet kapasitesi açısından bir seçenek ya da koşullu öneri sun.","Büyük müşteriyi seçebilmek için hangi ticari şartları değiştirmek istediğini ve karar kapılarını yaz."],"numbers":[{"id":"buyuk_kar","label":"Büyük sözleşmenin aylık faaliyet sonucu","value":320000,"unit":"TL/ay","tolerance":0.1,"why":"2.000.000×0,25−180.000=320.000."},{"id":"kucuk_kar","label":"Küçük portföyün aylık faaliyet sonucu","value":260000,"unit":"TL/ay","tolerance":0.1,"why":"1.200.000×0,35−160.000=260.000."},{"id":"fon","label":"Büyük sözleşmede ilk üç ay için rezerv dahil ek fonlama ihtiyacı","value":1840000,"unit":"TL","tolerance":0.1,"why":"Aylık ödeme 1.500.000+180.000=1.680.000;3 ay 5.040.000+başlangıç 300.000+rezerv 500.000−nakit 4.000.000=1.840.000."},{"id":"kucuk_nakit","label":"Küçük portföyde ilk ay sonu proje nakdi","value":3360000,"unit":"TL","tolerance":0.1,"why":"4.000.000−600.000+900.000−(780.000+160.000)=3.360.000. İkinci aydan itibaren aynı varsayımlarda aylık 260.000 artış."}],"rubric":[{"name":"Kâr ve nakit","evidence":"320.000 aylık kârın ilk üç ay nakit girişi olmadığını gösterir."},{"name":"Fonlama bütünü","evidence":"Başlangıç, değişken/sabit ödeme ve 500.000 rezervi birlikte hesaplar."},{"name":"Müşteri yoğunlaşması","evidence":"Tek müşteriye bağımlılığı gelir büyüklüğüyle örtmez; fesih/taahhüt koşullarını ister."},{"name":"Koşullu karar","evidence":"Peşinat, vade, aşamalı başlama ve finansman gibi müzakere seçeneklerini yetkili onayına bağlar."},{"name":"Küçük portföy gerçekçiliği","evidence":"40 müşterinin edinim/hizmet yükünü ve tahsilat varsayımını doğrular."},{"name":"Karar sunumu","evidence":"Alternatifleri aynı ufukta kıyaslar; fiyat veya vade değişirse önerinin nasıl değişeceğini açıklar."}],"update":{"title":"%30 peşinat teklifi","text":"Büyük müşteri her ayın satışının%30’unu o ay ödemeyi kabul ediyor; kalan%70 için ilk tahsilat hâlâ4. ayda. İlk üç ayda başlangıç ve 500.000 rezerv dahil fonlama açığı kapanır mı?","reference":"İlk 3 ay peşinat 3×600.000=1.800.000. Önceki 1.840.000 ihtiyaca karşı hâlâ40.000 TL açık var. Gün içi/hafta içi dip ve finansman giderleri de ayrıca incelenmeli. Aynı basit ufukta asgari peşinat 1.840.000/6.000.000≈%30,67 olur."},"solution":["Büyük 320.000, küçük 260.000 TL/ay faaliyet sonucu sağlar. Bu sıralama tek başına uygulanabilirlik kararı değildir.","Büyük seçenekte ilk 3 ay ödemeler 5.040.000 ve başlangıç 300.000;4 milyon kaynak 500.000 rezervle 1.840.000 TL kısa kalır.","Küçük portföy ilk ay 3.360.000 nakit bırakır ve baz vade varsayımıyla tamponu korur. Büyük seçenek ödeme/vade/finansman şartları değişirse savunulabilir; değişmiş şartların maliyeti yeniden hesaplanmalı."],"pitfalls":["Tahakkuk eden kârı aynı ay nakit girişi saymak.","Başlangıç giderini veya rezervi fonlama hesabında unutmak.","%30 peşinatın ihtiyacı yaklaşık karşıladığını söyleyip 40.000 açığı yok saymak."],"questions":["Büyük müşteri asgari hacim garantisi vermezse ne değişir?","Küçük müşterilerin tahsilatı da gecikirse hangi göstergeleri erken izlersin?"],"version":"1.0.0","candidateFile":"/cases/packs/buyuk-musteri-aday.md"}];

